quests[14180] = { id = 14180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwache der Silberschwingen kämpfen in der Kriegshymnenschlucht zum Schutze des Waldes. Wir unterstützen sie nicht deswegen, weil wir eine Liebe für Bäume haben, sondern weil der Wald dem Territorium der Allianz als natürliche Schutzbarriere dient.\n\nIhre Not ist heute größer als je zuvor. Wir müssen umgehend Verstärkung einsetzen, wenn wir nicht dabei zusehen wollen, wie das Eschental an das Brachland angegliedert wird!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Hervorragende Arbeit, {name}. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14181] = { id = 14181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, {class}! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", progress = "Ihr seid schon zurück? Bringt Ihr Siegesnachrichten?", completion = "Ihr habt der Horde heute ehrenvoll gedient, {name}. Der heutige Sieg sichert uns tausend weitere Siege!", sourceObjectiveStatus = "unverified-source-field" }
quests[14182] = { id = 14182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Wir werden den Feind bekämpfen und vernichten, wo auch immer wir ihn finden. Azeroth, die Scherbenwelt - der Ort spielt keine Rolle.\n\nWir können der Allianz nicht erlauben, im Auge des Sturms die Übermacht zu gewinnen. Tragt noch heute die Schlacht zu ihnen... Morgen könnte es schon zu spät sein!", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Ihr ehrt uns alle, {name}. Wir müssen dem Feind zeigen, dass wir ihn immer und überall bekämpfen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[14183] = { id = 14183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Feind, {name}. Sie behaupten, die Wälder des Eschentals zu verteidigen, um ihre Aggressionsakte gegen unsere Territorien im Brachland zu rechtfertigen.\n\nHeute haben wir die Möglichkeit, den Feind ein für alle Mal von unserem Land zu verjagen. Geht in die Kriegshymnenschlucht und holt zurück, was rechtmäßig uns gehört!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Die Horde steht in Eurer Schuld, {name}. Euer Mut und Einsatz während der Verteidigung unseres Landes macht uns alle stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[14199] = { id = 14199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Der Schwarze Ritter", description = "Mein Berufsgenosse, Erzmagier Timear hat mich gebeten, Euch vor etwas Schrecklichem zu warnen. Bald werdet Ihr an der Prüfung der Champions im Argentumkolosseum in Eiskrone teilnehmen. Nehmt Euch in Acht, denn es wird sich jemand einmischen, den sie den Schwarzen Ritter nennen.\n\nBringt mir ein Fragment seiner Seele, damit die Kirin Tor wissen, dass er erledigt ist. Mir wurde gesagt, dass, solltet Ihr versagen, dies Euer eigenes Verderben sei.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein Seelenfragment des Schwarzen Ritters bringt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \"Heroisch\" abgeschlossen werden.", progress = "Ist es so, wie Timear es vorhergesehen hat? Ist der Schwarze Ritter unerwartet aufgetaucht?", completion = "Es ist gut zu sehen, dass Ihr siegreich aus der Prüfung hervorgegangen seid. Wahrlich, Ihr seid ein Champion - und zwar nicht nur für den Argentumkreuzzug, sondern in der Tat auch für die Kirin Tor.\n\nMan kann nur hoffen, dass Ihr dem dunklen Bösewicht den letzten Stoß verpasst habt und es das Letzte sein wird, das wir von ihm gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14203] = { id = 14203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässtes Rezept", description = "Dies scheinen die Überreste eines Rezepts für starken Wein zu sein. Vielleicht wäre der Eigentümer von Noch ein Gläschen in Dalaran daran interessiert...", sourceObjective = "Bringt das durchnässte Rezept zu Christi Stockton nach Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[14349] = { id = 14349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl", description = "Der Befehl ist gekommen, {class}. Sylvanas selbst hat verlangt, dass ich meine 'tüchtigsten' Agenten auf eine höchst diffizile taktische Mission nach Unterstadt schicke.\n\nLeider wurden meine tüchtigsten Agenten alle vor drei Jahren getötet. An ihrer Stelle habe ich eine Bande hirntoter Trottel.\n\n<Nathanos schaut Euch kalt an.>\n\nReist sofort nach Unterstadt und erstattet der dunklen Fürstin Bericht. Macht mir keine Schande, {class}!", sourceObjective = "Reist nach Unterstadt und sprecht mit Fürstin Sylvanas Windläufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14350] = { id = 14350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Purpurrote Kurier", description = "Wir können die Oberbefehlshaber des Scharlachroten Kreuzzugs nicht direkt angreifen; sie verfügen über eine zu gute Verteidigung. Aber bekanntlich führen viele Wege zum Ziel. Ohne ihre Hauptstreitkraft sind sie hilflos.\n\nMeine Todespirscher haben Daten über die Aktivitäten des Kreuzzugs außerhalb von Stratholme gesammelt. Jeden Tag wird ein Bericht aus ihrer Befehlszentrale nach Tyrs Hand geschickt. Dieser Bericht ist der Schlüssel, {race}! Sucht den Purpurroten Kurier und beschafft diesen Bericht. Bringt ihn zu Nathanos.", sourceObjective = "Kehrt in die östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des obersten Kreuzzüglers.\n\nBringt den Befehl zu Nathanos Pestrufer und wartet auf weitere Anweisungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14351] = { id = 14351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht des Hügellands gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.\n\nBringt die versiegelte Belobigung zu Bragor Blutfaust nach Unterstadt. Geht erhobenen Hauptes, {class}.", sourceObjective = "Bringt Darthalias versiegelte Belobigung zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14352] = { id = 14352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unheilige Allianz", description = "Mylady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf Weiteres abseits der Hügel der Klingenhauer aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin", sourceObjective = "Bringt die kleine Rolle zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14353] = { id = 14353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unheilige Allianz", description = "Angeblich hält sich dieser Malcin außerhalb der Hügel der Klingenhauer auf. Keine Frage - er muss sterben.\n\nMeine Kontakte in Orgrimmar erzählen mir, dass ihre Späher dort unten Anzeichen der Seuche gefunden haben. Die Stacheleber weisen auch Anzeichen einer Verseuchung auf und sie sind um einiges stärker. Was auch immer die Geißel dort unten unternimmt, muss ein Ende haben. Jetzt sofort.\n\nFindet diesen Malcin und schaltet ihn aus. Meldet Euch wieder bei mir, sobald er tot ist.", sourceObjective = "Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14355] = { id = 14355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Scharlachrote Kloster", description = "Eine meiner Aufgaben, während ich hier stationiert bin, ist es, den Verlassenen dabei zu helfen, ihre Grenzen zu überwachen - und das ist exakt das, was Ihr, {class}, für mich erledigen werdet.\n\nIch mag am Leben sein, doch ist der Scharlachrote Kreuzzug bereit, meine Leute genau so schnell niederzumähen wie einen der Untoten. Sie sind ein Problem hier, ein großes sogar, und Ihr werdet etwas dagegen unternehmen.\n\nGeht zum Kloster und erschlagt Hochinquisitorin Weißsträhne und ihre Offiziere.", sourceObjective = "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Bragor Blutfaust in Unterstadt.", completion = "Ich bin mir sicher, dass Sylvanas erfreut sein wird, dass dieses Problem gelöst wurde, {name}. Der Auftrag, den ich Euch erteilte, war kein einfacher, und doch seid Ihr hier, siegreich. Das verlangt Respekt und was Ihr getan habt, wird nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14356] = { id = 14356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht zu Zerstören...", description = "Zugehört, {class}.\n\nIhr mögt vielleicht nichts davon wissen, aber Orgrimmar hat ein Problem. Tief im Flammenschlund treibt eine Sekte des Schattenrats, die sich 'Die Sengende Klinge' nennt, ihr Unwesen. Es sind hauptsächlich Orcs und ich kann vertrauliche Informationen nicht in die Hände der Grunzer dort legen. Hier kommt Ihr ins Spiel.\n\nSie sollten zwei Bücher in ihrem Besitz haben. Ich möchte sie weder der Sengenden Klinge noch den Verlassenen überlassen. Bringt sie direkt zu mir.", sourceObjective = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Bragor Blutfaust nach Unterstadt.", progress = "Habt Ihr die Bücher in Sicherheit bringen können? Sie dürfen nicht in die falschen Hände gelangen.", completion = "Gut, {class}, das habt Ihr gut gemacht. Ich werde sie sicher verwahren und vor neugierigen Blicken verbergen; das Letzte, was wir brauchen, ist ein wiedererstarkter Schattenrat.\n\nMeldet Euch in der Zukunft wieder bei mir; ganz offensichtlich gibt es hier immer etwas zu tun und ich könnte ein Paar fähige Hände bestimmt gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14409] = { id = 14409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine vorsichtige Rückkehr", description = "Schenkt mir einen Moment Eurer Zeit, {class}.\n\nVeränderung liegt in der Luft. Sie hat uns aus den Ruinen Eldre'Thalas' gezogen, ein weiteres Mal hinaus in die weite Welt. Ich bin gekommen, um diese Stadt zu erforschen und darf von dieser Aufgabe nicht abweichen, doch wenn Ihr interessiert wärt, hätte ich einen Auftrag für Euch.\n\nMein Kollege ist auf dem Weg nach Darnassus, um mit der Hohepriesterin zu sprechen, auf dass wir eine Übereinkunft erreichen. Nehmt dieses Tagebuch und bringt es zu Mordent Schattenfall im Tempel. Es könnte ihm bei seiner diplomatischen Mission nützlich sein.", sourceObjective = "Bringt Mordent Schattenfall in DarnassusDaros' Tagebuch.", progress = "Es scheint, als hätte ich Zeit für eine Unterredung. Worum geht es?", completion = "Ah, Daros' Aufzeichnungen. Er war schon immer ein sehr sorgfältiger Chronist des Fortschritts. Seine Worte könnten helfen, zu erklären, wie weit wir gekommen sind.\n\nIhr habt meinen Dank dafür, dass Ihr mir dies hier gebracht habt, {race}. Vielleicht werden wir einander häufiger sehen, sobald erkannt wurde, dass wir niemandem schaden wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14418] = { id = 14418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Syndikat? Darauf wäre ich nie gekommen. Offenbar sind die Lords von Alterac in den Jahren seit ihrem Verrat tief gesunken.\n\nHawkins wird es mit Freuden hören, und da wir diese Entdeckung weitgehend Euch verdanken, ist es nur recht und billig, dass Ihr ihm die Nachricht überbringt.\n\nAh, und wie konnte ich das vergessen?\n\nWillkommen bei den Todespirschern.", sourceObjective = "Bringt Androns Geschäftsbuch zu Aleric Hawkins in die Halle der dunklen Fürstin in Unterstadt.", progress = "Ja?", completion = "Hmm, das ist interessant. Die Todespirscher haben ihre Pflicht bei der Erledigung dieser Aufgabe meisterlich erfüllt.\n\nWie mir gesagt wurde, verdient Ihr eine Belohnung für das, was Ihr in dieser Sache geleistet habt. Immer weiter so, {name}; die Todespirscher haben immer Verwendung für gute Männer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14419] = { id = 14419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Vorstellungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.\n\nUnser Anführer vermutet, dass Andron einer anderen Gruppe Unterstützung zuteilwerden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.\n\nIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", sourceObjective = "Sprecht mit Andron Gant in Unterstadt.", progress = "Hallo. Kann ich etwas für Euch tun?", completion = "Ah, ja, ich habe Euch erwartet. Ich darf davon ausgehen, dass unsere gemeinsamen Bekannten mit den Informationen, die ich bisher lieferte, zufrieden waren?\n\nVermutlich hat es keinen Sinn, Euch zu fragen. Ich bezweifle, dass sie Euch mit diesem Wissen belasten würden. Warum so viel Vertrauen in den Boten setzen, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[14420] = { id = 14420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache der dunklen Fürstin, so müsst Ihr Euren Wert beweisen.\n\nIch will Euch nichts vormachen, {name}, diese Aufgabe könnte Euren Tod bedeuten.\n\nIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Unterstadt pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.\n\nJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", sourceObjective = "Beschafft Astors Vorstellungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", progress = "Erfolgsmeldung?", completion = "Gut gemacht, {name}. Ihr habt den ersten Teil dieser Prüfung bestanden. Hoffentlich hat Andron keinen Wind von Euren Aktivitäten bekommen, sodass wir ihn davon überzeugen können, dass Ihr wirklich der Bote seid, den er erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14421] = { id = 14421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", sourceObjective = "Bringt Androns Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Unterstadt.", progress = "Erfolg, {name}?", completion = "Das sind eindeutig mehr Informationen, als ich mir je von Andron erhofft hätte. Lasst sie mich einen Moment studieren, bevor ich Euch Eure nächste Aufgabe nenne.", sourceObjectiveStatus = "unverified-source-field" }
quests[14436] = { id = 14436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenbuddelei", description = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.\n\nSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.\n\nIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Donnerfels, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.", sourceObjective = "Sammelt 5 Ausgrabungsleiterhacken ein.\n\nZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.\n\nBringt Ahmo Donnerhuf im Dorf der Bluthufe 5 zerbrochene Werkzeuge.", sourceObjectiveStatus = "unverified-source-field" }
quests[14437] = { id = 14437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, {name}.\n\nReist ins Dorf der Bluthufe und sprecht mit Ahmo Donnerhuf. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Donnerfels verdienen.\n\nBringt Ahmo dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.\n\nFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr könntet Euch sonst verirren.", sourceObjective = "Bringt Ahmo Donnerhuf im Dorf der Bluthufe Falkenwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14438] = { id = 14438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Nutzung des Landes", description = "Viele Konflikte verwunden dieses Land, {name}. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.\n\nBleichmähnengnolle haben sich südlich vom Dorf der Bluthufe und in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.\n\nWorte allein genügen nicht mehr als Antwort.", sourceObjective = "Tötet 10 Gerber der Bleichmähnen, 8 Kürschner der Bleichmähnen und 5 Wilderer der Bleichmähnen und kehrt dann zu Ahmo Donnerhuf ins Dorf der Bluthufe zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[14439] = { id = 14439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Donnerfels", description = "Jetzt wird man Euch in unserer großen Stadt verehren. <Ein/Eine:r> {race}, <der/die:r> würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.\n\nSucht unseren jungen Anführer Baine Bluthuf auf, um Eure letzte Aufgabe zu erhalten. Er residiert auf der höchsten Anhöhe in Donnerfels.", sourceObjective = "Sprecht mit Baine Bluthuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[14440] = { id = 14440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Donnerfels verdient.\n\nUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.\n\nWir sind Jäger, {name}. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.", sourceObjective = "Baine Bluthuf in Donnerfels möchte, dass Ihr ihm das Horn von Arra'chea bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14441] = { id = 14441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garroshs Autogramm", description = "Man sagt, dass Garrosh Höllschrei einer der größten Helden der Horde ist! Wenn ich einmal groß bin, will ich auch so ein Held sein!\n\nKennst du Garrosh, {name}? Könntest du mir einen Gefallen tun, bitte? Kannst du sein Autogramm für mich bekommen? Ich weiß nicht, wie ich ihn fragen soll, und wahrscheinlich würde er jemandem wie mir gar nicht zuhören... aber du! Du bist ein Abenteurer wie er! Ich wette, dass er dir mir nichts, dir nichts ein Autogramm geben wird!\n\nBitte?", sourceObjective = "Reist nach Orgrimmar und kümmert Euch darum, für Euren Schützling ein Autogramm von Garrosh Höllschrei zu bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14443] = { id = 14443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ramponierte Schwertgriff", description = "Dieser ramponierte alte Schwertgriff hat schon bessere Tage gesehen. Bevor er von der Klinge gebrochen wurde, muss es sich dabei um ein wunderschönes Beispiel der Schmiedekunst gehandelt haben.\n\nDie eleganten Symbole und exotischen Edelsteine, die den Griff schmücken, lassen darauf schließen, dass die Waffe womöglich einer mächtigen Person gehörte. Der Silberbund wäre sicherlich am Fund eines solchen Artefakts interessiert. Sucht ihren Repräsentanten in Quel'Delars Ruh südlich des Argentumturnierplatzes auf.", sourceObjective = "Bringt den ramponierten Schwertgriff zu Caladis Prunkspeer in Quel'Delars Ruh südlich des Argentumturnierplatzes.", sourceObjectiveStatus = "unverified-source-field" }
quests[14444] = { id = 14444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Drachen", description = "Es gibt keinen Zweifel: Dieser Schwertgriff stammt von einer mächtigen, uralten Waffe - aber welcher? Ich kann mich nicht daran erinnern, ein Schwert mit solchen Markierungen gesehen oder davon gehört zu haben, was jedoch nicht heißt, dass wir in einer Sackgasse gelandet sind.\n\nKorialstrasz, besser bekannt als Krasus, ist schon seit Langem ein Freund der Quel'dorei und der Kirin Tor. Seinem immensen Wissen und seinen gewaltigen Ressourcen nach zu urteilen wird er mit Sicherheit etwas wissen. Reist zur Spitze des Wyrmruhtempels und ersucht ihn um Rat. Meldet Euch anschließend bei Arkanist Tybalin im Inneren der Silbernen Enklave in Dalaran.", sourceObjective = "Sprecht mit Krasus in der Spitze des Wyrmruhtempels.", sourceObjectiveStatus = "unverified-source-field" }
quests[14457] = { id = 14457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan der Sonnenhäscher", description = "Einer meiner Kontakte unten in den Kanälen der Schattenseite hat in der Nähe des Schwarzmarktes einen Agenten der Sonnenhäscher erblickt. Die Sonnenhäscher sind normalerweise nicht dafür bekannt, ein Interesse am dortigen Treiben zu hegen, was also sehr stark darauf hindeutet, dass sie etwas vorhaben.\n\nBegebt Euch zur Schattenseite, spürt diesen Agenten auf und kümmert Euch um ihn. Durchsucht ihn nach allen Informationen, die uns einen Hinweis über den Verbleib dieses Folianten vom Wyrmruhtempel liefern könnten. Wir können nicht zulassen, dass sie ihn zuerst zurück nach Eiskrone bringen.", sourceObjective = "Gelangt an die Befehle der Sonnenhäscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[14483] = { id = 14483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas liegt in der Luft (und Liebe ist es nicht)", description = "Auf die Innenseite der Karte sind verrückte, detaillierte Pläne gekritzelt, einen Großteil Azeroths zu infizieren. Das müsst Ihr sofort einem der Ermittler des Dampfdruckkartells zeigen!", sourceObjective = "Bringt die vergilbte schöne Grußkarte zu Detektiv Snap Schnappbolz in Orgrimmar.", progress = "Habt Ihr Euch um diese nichtsnutzigen, Ränke schmiedenden Gauner gekümmert?", completion = "Was habt Ihr da?\n\nOh, hey, das ist was Großes. Was richtig Großes. Die ganzen verrückten Details auf einem Haufen. Danke - Ihr habt uns hier echt geholfen. Es war schön, mit Euch zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14488] = { id = 14488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustellung", description = "Ihr habt es geschafft? Gut. Ich habe schon auf Hilfe gewartet. Jetzt ist die beste Zeit, zu handeln.\n\nNehmt dieses Paket und begebt Euch noch tiefer hinein, um Hummel, dem Leiter dieser dreckigen Chemiemanufaktur, ein paar Dokumente zuzustellen. Das Dokument ist hier drin, zusammen mit einer kleinen Hilfe, falls sie irgendwelche chemischen Überraschungen für Euch bereit halten. Verwendet einen der Neutralisatoren, wenn es soweit kommt, okay?", sourceObjective = "Stellt Apotheker Hummel auf Burg Schattenfang die Vorladung bei Gericht zu.", progress = "Ich kann mich nicht erinnern, einen Reinigungsdienst bestellt zu haben... aber ja, ich bin Apotheker Hummel.\n\n...Moment mal, was hat das alles zu bedeuten? Glaubt Ihr etwa, diese bedeutungslosen Papiere könnten mich aufhalten? Pah!", completion = "Was wir hier tun, hat Euch nicht zu interessieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[20438] = { id = 20438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Verkleidung", description = "Euch ins Innere von Sonnenhäschers Zuflucht zu bringen, wird schwieriger sein, als es erscheint. Nur diejenigen, die über einen Wappenrock der Sonnenhäscher verfügen, wird Zugang zur Zuflucht gewährt. Sollten wir an einen herankommen können, wird eine einfache Verzauberung den Rest erledigen.\n\nAuf dem Balkon über den Fäden des Schicksals werdet Ihr Shandy Lackglanz finden. Ich habe ihm in der Vergangenheit ein paar Mal geholfen - er schuldet mir also noch einen Gefallen. Er kümmert sich um die Wäsche etlicher Leute jeden Schlags aus der Stadt. Vielleicht kann er einen Weg finden, Euch einen Wappenrock eine Weile lang \"auszuleihen\".", sourceObjective = "Besorgt Euch von Shandy Lackglanz einen geliehenen Wappenrock.", sourceObjectiveStatus = "unverified-source-field" }
quests[20439] = { id = 20439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit dem Magister", description = "Ich habe eine Verzauberung auf den Wappenrock gelegt, die es Euch erlauben sollte, einen kurzen Augenblick lang unentdeckt an den Verteidigungsvorkehrungen der Zuflucht der Sonnenhäscher vorbeizukommen. Das sollte Euch genug Zeit geben, das Rattenloch zu betreten und Euch dort mit unserem Kontakt bei den Sonnenhäschern, einem gewissen Magister Hathorel, zu treffen.\n\nBesorgt Euch die Kopie von \"Uralte drachengeschmiedete Klingen\", die seine Männer aus Wyrmruh entliehen haben, solange Eure Verkleidung anhält, und kehrt zu mir zurück.", sourceObjective = "Besorgt den Folianten \"Uralte drachengeschmiedete Klingen\" von Magister Hathorel.", sourceObjectiveStatus = "unverified-source-field" }
quests[24216] = { id = 24216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Gegner, {name}. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24217] = { id = 24217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Gegner, {name}. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24218] = { id = 24218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Hervorragende Arbeit, {name}. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[24219] = { id = 24219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24220] = { id = 24220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Das sind gute Neuigkeiten, {class}! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24221] = { id = 24221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, {class}! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24223] = { id = 24223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24224] = { id = 24224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24225] = { id = 24225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Gegner, {name}. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24226] = { id = 24226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, {class}! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24426] = { id = 24426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, {name}. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24427] = { id = 24427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, {name}, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[24428] = { id = 24428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höchst merkwürdiger Umstand", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und bringt ihn Zardeth der Schwarzen Klaue.", sourceObjective = "Bringt Onyxias Kopf zu Zardeth der Schwarzen Klaue im Keller des geschlachteten Lamms.", progress = "Bei Nozdormus Zähnen!", completion = "Was? Wie seid Ihr an diesen Kopf gekommen? Ist sie nicht... Nein, die Details sind nicht wichtig vermute ich. Ihr werdet unzweifelhaft ein wenig von diesem Tand als Vergütung erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24429] = { id = 24429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höchst merkwürdiger Umstand", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und bringt ihn Neeru Feuerklinge.", sourceObjective = "Bringt Onyxias Kopf zu Neeru Feuerklinge in der Kluft der Schatten.", progress = "Was hat das zu bedeuten?!", completion = "Ihr habt mir das Haupt von jemandem gebracht, der... Nein, es wäre das Beste, nicht zu viel darüber nachzudenken. Ihr werdet unzweifelhaft eine Vergütung für Eure Heldentaten erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24431] = { id = 24431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässtes Rezept", description = "Dies scheinen die Überreste eines Rezepts für starken Wein zu sein. Vielleicht wäre der Eigentümer von Noch ein Gläschen in Dalaran daran interessiert...", sourceObjective = "Bringt das durchnässte Rezept zu Christi Stockton nach Dalaran.", progress = "\"Wein ist nur so fein, wie derjenige, der ihn trinkt\", sag ich immer.", completion = "Das ist ein ziemlicher Fund, {name}. Ich kann Euch nicht erlauben, das an irgendwen anderen zu verkaufen, also bin ich gewillt, Euch ein großzügiges Angebot zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24442] = { id = 24442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlachtpläne der Kvaldir", description = "Ein Blick auf die erbeuteten Angriffspläne lässt eine Karte von den östlichen Königreichen und Kalimdor erkennen, auf der die größten Siedlungen markiert sind. Beim Lesen der Befehle erfahrt Ihr, dass die Hauptleute der Kvaldir Pläne für eine Reihe von zerstörerischen Schlachtzügen ausgearbeitet haben.\n\nLaut diesen Befehlen sollen die Angriffe anfangen, nachdem Nebelrufer Yngvar \"das Herz der Nebel befragt hat\". Möglicherweise könnt Ihr die Angriffe ein wenig hinauszögern, indem Ihr das Omen aus der Höhle der Nebelrufer westlich von Hrothgars Landestelle erbeutet und Justiziarin Mariel Treuherz benachrichtigt.", sourceObjective = "Bergt das Herz der Nebel und bringt es zusammen mit den Angriffsplänen der Kvaldir zu Jusitziarin Mariel Treuherz auf dem Argentumturnierplatz.", progress = "Was habt Ihr da gefunden, {name}?", completion = "<Mariel nimmt die Befehle und den erbeuteten Seher-Kristall entgegen und begutachtet beides.>\n\nGute Arbeit, {name}, und gut mitgedacht. Ich bin mir zwar sicher, dass der Diebstahl dieses Schmuckstücks sie nicht lange aufhalten wird, aber ich glaube, dass Ihr uns Zeit verschafft habt, die Anführer der Horde und der Allianz vor den bevorstehenden Angriffen zu warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24451] = { id = 24451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz mit dem Arkanisten", description = "Ich habe den Wappenrock mit einem Zauber belegt, sodass Ihr für kurze Zeit die Verteidigung der Silbernen Enklave umgehen könnt. Das dürfte Euch genügend Zeit verschaffen, um in die obere Ebene der Silbernen Enklave zu gelangen und jemanden vom Silberbund namens Arkanist Tybalin zu treffen.\n\nNutzt Eure Tarnung, um das Exemplar von \"Uralte drachengeschmiedete Klingen\", das seine Leute von Wyrmruh geliehen haben, zu beschaffen und zu mir zu bringen.", sourceObjective = "Holt den Folianten \"Uralte drachengeschmiedete Klingen\" bei Arkanist Tybalin.", progress = "Habt Ihr das Buch vom Wyrmruhtempel besorgt?", completion = "Ausgezeichnete Arbeit! Jetzt, wo es sich in unserem Besitz befindet, müssen wir es so schnell wie möglich zu Myralion Sonnenfeuer bringen. Wir dürfen nicht riskieren, dass das Buch wieder in die Hände des Silberbunds gelangt.\n\nIch kümmere mich darum, dass Shandy Lackglanz seinen Wappenrock unbeschadet zurückbekommt und für seine Hilfe entschädigt wird. Sobald sich das Buch in Myralions Händen befindet, stellt der Silberbund keine Bedrohung mehr dar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24454] = { id = 24454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Caladis Prunkspeer zurück", description = "Wir müssen dieses Buch umgehend zu Caladis Prunkspeer bringen. Würdet Ihr das tun? Ich kann mich auf niemand anderen verlassen, das Buch zu transportieren, und Ihr habt Euch geschickt darin erwiesen, die Sonnenhäscher auf Abstand zu halten.\n\nBringt es nach Quel'Delars Ruh südlich des Argentumturnierplatzes in Eiskrone. Caladis und das Schwert werden auf Euch warten. Je eher wir die Klinge identifizieren, desto eher können wir Anspruch darauf erheben.", sourceObjective = "Bringt \"Uralte drachengeschmiedete Klingen\" zu Caladis Prunkspeer nach Quel'Delars Ruh.", sourceObjectiveStatus = "unverified-source-field" }
quests[24461] = { id = 24461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert neu schmieden", description = "Wir dürfen nicht zulassen, dass Quel'Delar in zerbrochenem und entehrtem Zustand bleibt. Nehmt die Überreste des Schwertes sowie den von Euch gefundenen ramponierten Schwertgriff und begebt Euch in die Grube von Saron in der Eiskronenzitadelle.\n\nIn der Grube lässt der Lichkönig Sklaven Saroniterz fördern sowie be- und verarbeiten. Dieses energieerfüllte Saronit brauchen wir, um Quel'Delar wiederherzustellen.\n\nIhr müsst energieerfüllte Saronitbarren sammeln und den Hammer des Schmiedemeisters erbeuten, Euch mit beidem zum Amboss des Schmiedemeisters begeben und das Schwert neu schmieden.", sourceObjective = "Besorgt 5 energieerfüllte Saronitbarren sowie den Hammer des Schmiedemeisters und schmiedet damit Quel'Delar neu.", sourceObjectiveStatus = "unverified-source-field" }
quests[24476] = { id = 24476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge tempern", description = "Endlich wurden die Bruchstücke von Quel'Delar wieder vereint und die Klinge ist ganz - doch sie muss zuerst getempert werden, bevor Ihr sie einsetzen könnt. Die gezackte Saronitschneide ist spröde und würde beim ersten Kontakt zerbrechen.\n\nIn den Tiefen der Seelenschmiede in der Eiskronenzitadelle gibt es einen Ort, an dem sie sicher getempert werden kann. Nehmt Quel'Delar mit Euch zum Domizil des Verschlingers der Seelen und sucht nach dem Schmelztiegel. Taucht die Klinge dort hinein und bringt sie zurück zu mir in die gefrorenen Hallen.", sourceObjective = "Tempert das neugeschmiedete Quel'Delar im Schmelztiegel der Seelen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24480] = { id = 24480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen der Reflexion", description = "Ihr habt das Schwert zwar neu geschmiedet und getempert, dennoch ruht es in seiner Scheide und zeigt nichts von der Macht, die es besitzen soll. Ihr sagt, dass es Euch zieht, als hätte es einen eigenen Willen?\n\nWagt Ihr es, das Schwert an den von ihm gewünschten Ort zu bringen? Es ist nicht richtig, dass es so ruhig und doch so hartnäckig ist, und ich fürchte, wir werden nie erfahren weshalb, solltet Ihr es nicht an seinen Zielort bringen. Bringt es in die Hallen der Reflexion in der Eiskronenzitadelle. Seid jedoch auf der Hut! Ich warte in den gefrorenen Hallen auf Euch.", sourceObjective = "Bringt Quel'Delar nach Schwertruh ins Innere der Hallen der Reflexion.", sourceObjectiveStatus = "unverified-source-field" }
quests[24498] = { id = 24498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad zur Zitadelle", description = "Sie haben unsere gefangenen Soldaten zur Arbeit im Steinbruch eingesetzt! {class}. Tötet ihre Entführer und befreit sie. Tut dies schnell. Wir werden ihre Hilfe brauchen, wenn wir Geißelfürst Tyrannus entgegentreten.", sourceObjective = "Befreit 15 Allianzsklaven und tötet Schmiedemeister Garfrost.", completion = "Ihr habt heute gute Arbeit geleistet. Jetzt, wo viele der Sklaven befreit sind und wir Zugang zu den Schmieden haben, wird es nicht mehr lange dauern, bis ich eine starke Mannschaft zusammen habe, die uns helfen wird, uns aus den Fängen des Geißelfürsten Tyrannus und seiner widerwärtigen Grube zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[24499] = { id = 24499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos gequälter Seelen", description = "Ich kann Euch gar nicht genug danken, dass Ihr gekommen seid! Wir sind eindeutig zu wenige, um uns in die Zitadelle zu wagen, doch so eine Gelegenheit dürfen wir uns nicht entgehen lassen.\n\nIch erwarte die Ankunft von Champions aus dem Kolosseum, doch wenn es stimmt, was man über Euch erzählt, solltet Ihr Euch auch allein durch die Schmiede kämpfen können. Bereitet einen Weg zum anderen Ende und sichert den Pfad zur Grube von Saron, damit unsere Leute weiter in die Zitadelle vordringen können.\n\nBitte beeilt Euch, {name}! Wir verlassen uns auf Euch.", sourceObjective = "Tötet Bronjahm und den Verschlinger der Seelen, um den Zugang zur Grube von Saron zu sichern.", completion = "Genau zur rechten Zeit! Danke, {name}!\n\nDie Grube von Saron liegt direkt vor uns, und wenn unsere Späher richtig liegen, befinden sich dahinter die Hallen der Reflexion. Diesen Ort lässt Arthas nicht so stark bewachen, und an diesem Ort hoffen wir, ein Anzeichen von Schwäche bei ihm entdecken zu können... und vielleicht, aber nur vielleicht, ihn zu erlösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24500] = { id = 24500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Lichkönigs", description = "Uther wusste viel darüber, wie Arthas möglicherweise zu schlagen ist. Es besteht wohl kaum Hoffnung, Arthas auf den Stufen seines eigenen Thrones zu besiegen. Und wer übernimmt in diesem Fall die Krone des Lichkönigs?\n\nViele Fragen sind noch offen, doch die von Euch gelieferten Antworten könnten ausschlaggebend für einen Sieg über Arthas sein. Ihr müsst Jaina finden und vor dem Lichkönig fliehen, so lange Zeit dazu ist.", sourceObjective = "Findet Lady Jaina Prachtmeer und flieht aus den Hallen der Reflexion.", completion = "<Jaina ringt noch immer nach Luft.>\n\nIch kann kaum glauben, dass wir noch am Leben sind. Es war dumm von mir, ihm zu folgen. Zu oft habe ich diesen Fehler begangen. Und Ihr... es war ziemlich unbesonnen, mir zu folgen, anstatt mit den Informationen zu fliehen. Aber... nun ja... danke. Das war wirklich heldenhaft!\n\nMit Uthers Hilfe haben wir vielleicht eine Chance, Arthas zu besiegen. Dann hätten alle, die heute gestorben sind, ihr Leben nicht umsonst gelassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24506] = { id = 24506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der eisigen Zitadelle", description = "{class}! Kommt schnell her - ich muss mit Euch reden!\n\nMeine Königin, Fürstin Sylvanas Windläufer, hat eine Lücke in der Verteidigung der Eiskronenzitadelle entdeckt, die zu einem Ort namens \"Die Seelenschmiede\" führt. Bevor sie sich auf den Weg machte, hat sie mich mit der Suche nach grimmigen Kämpfern beauftragt, die sich dorthin wagen. Ihr scheint mir dafür geeignet.\n\nTrefft sie am Eingang der Schmiede, {class}!", sourceObjective = "Betretet die Seelenschmiede von der Seite der Eiskronenzitadelle und findet Fürstin Sylvanas Windläufer.", completion = "Gut. {name}, ich weiß einiges über Euch. Ihr seid wie gemacht für diese Aufgaben.\n\nUns bietet sich die seltene Gelegenheit, die Eiskronenzitadelle zu erkunden. Doch wir müssen uns beeilen, wenn wir nicht wollen, dass Arthas etwas merkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24507] = { id = 24507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad zur Zitadelle", description = "Sie lassen unsere entführten Soldaten im Steinbruch schuften. Tötet die Entführer und befreit die Gefangenen, {class}! Beeilt Euch! Wir brauchen ihre Hilfe, wenn wir Geißelfürst Tyrannus gegenübertreten.", sourceObjective = "Befreit 15 Hordensklaven und tötet Schmiedemeister Garfrost.", progress = "Danke, {class}. Unser Blut und unser Stahl werden Euch zu Diensten sein.", completion = "Ihr habt heute gute Arbeit geleistet. Jetzt, wo viele der Sklaven befreit sind und wir Zugang zu den Schmieden haben, wird es nicht mehr lange dauern, bis ich eine starke Mannschaft zusammen habe, die uns helfen wird, uns aus den Fängen des Geißelfürsten Tyrannus und seiner widerwärtigen Grube zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[24510] = { id = 24510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der eisigen Zitadelle", description = "{class}! Kommt schnell her - ich muss mit Euch reden!\n\nMeine Herrin, Lady Jaina Prachtmeer, hat eine Lücke in der Verteidigung der Eiskronenzitadelle entdeckt, die zu einem Ort namens \"Die Seelenschmiede\" führt. Bevor sie sich auf den Weg machte, erhielt ich die Aufgabe, alle Hilfe zu suchen, die ich finden kann... und, nun ja, ich hatte da an Euch gedacht.\n\nBitte, sucht sie so schnell wie möglich dort auf!", sourceObjective = "Betretet die Seelenschmiede von der Seite der Eiskronenzitadelle und findet Lady Jaina Prachtmeer.", completion = "{name}! Ich bin so froh, dass Ihr gekommen seid!\n\nUns bietet sich die seltene Gelegenheit, die Eiskronenzitadelle zu erkunden. Doch wir müssen uns beeilen, wenn wir nicht wollen, dass Arthas etwas merkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24511] = { id = 24511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos gequälter Seelen", description = "Ich bin froh, dass wir in Euch <einen fähigen Helfer/eine fähige Helferin> haben! Es ist ziemlich gefährlich, mit so wenig Leuten die Zitadelle zu betreten, doch so eine Gelegenheit bekommt man nicht alle Tage.\n\nIch erwarte die Ankunft von Champions aus dem Kolosseum, doch wenn es stimmt, was man über Euch erzählt, solltet Ihr Euch auch allein durch die Schmiede kämpfen können. Bereitet einen Weg zum anderen Ende und sichert den Pfad zur Grube von Saron, damit unsere Leute weiter in die Zitadelle vordringen können.\n\nBeeilt Euch, {name}! Wir haben nicht viel Zeit.", sourceObjective = "Tötet Bronjahm und den Verschlinger der Seelen, um den Zugang zur Grube von Saron zu sichern.", completion = "Ihr kommt gerade recht, {class}!\n\nDie Grube von Saron liegt direkt vor uns, und wenn unsere Späher richtig liegen, befinden sich dahinter die Hallen der Reflexion. Diesen Ort lässt Arthas nicht so stark bewachen, und an diesem Ort hoffen wir, ein Anzeichen von Schwäche bei ihm entdecken zu können... und eine Möglichkeit zur Rache, die schon so lange überfällig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24522] = { id = 24522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Sonnenbrunnen", description = "Bringt Quel'Delar so schnell wie möglich zum Sonnenbrunnen, {name}! Glaubt Uthers Worten, dass Ihr die Kontrolle über die Klinge nicht immer behalten könnt, wenn sie dem bösen Einfluss des Lichkönigs ausgesetzt ist. Ihr müsst zur Insel von Quel'Danas reisen und versuchen, zum Sonnenbrunnen zu gelangen, um das Schwert zu läutern.\n\nDie Wächter des Sonnenbrunnens werden Euch nicht so einfach Zutritt gewähren. Daher müsst Ihr Euch an Halduron Wolkenglanz wenden, der ein Auge auf die Wachen dort hat.", sourceObjective = "Sprecht mit Halduron Wolkenglanz am Eingang des Sonnenbrunnenplateaus auf der Insel von Quel'Danas.", sourceObjectiveStatus = "unverified-source-field" }
quests[24535] = { id = 24535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dämmersucher", description = "Solltet Ihr Quel'Delar wirklich bei Euch tragen, {name}, kann ich Euch vielleicht Zutritt zum Sonnenbrunnen verschaffen. Wenn Ihr die Geschichte der Klinge kennt, erinnert Ihr Euch vielleicht, dass Thalorien Dämmersucher sie bei der Verteidigung des Sonnenbrunnens gegen die Geißel führte. Er fiel dort, wo sich heute die Todesschneise befindet, und verschaffte so seinen Leuten Zeit, eigene Vorbereitungen zu treffen. Seine sterblichen Überreste befinden sich am südlichen Ende der Todesschneise auf dieser Insel. Begebt Euch dorthin, damit sein Geist Euch den Segen erteilt, zum Sonnenbrunnen zu gehen.", sourceObjective = "Besucht die sterblichen Überreste Thalorien Dämmersuchers und erhaltet seinen Segen zum Führen Quel'Delars.", sourceObjectiveStatus = "unverified-source-field" }
quests[24536] = { id = 24536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas stinkt hier", description = "Man sieh sich diese Kerle an. Das Dampfdruckkartell betreibt das Valentinstagsgeschäft schon seit Jahren, und plötzlich tauchen diese Typen auf. Die gehören nicht zum Kartell. Das Kartell hat mich beauftragt, der Sache auf den Grund zu gehen. Irgendwas stinkt hier, und damit meine ich nicht das Parfüm.\n\nNehmt das Gerät, das ich mitgebracht habe, um damit die Parfümwolken zu untersuchen, die die Wachen umgeben. Ich möchte wissen, was sie in das Zeug reintun. Irgendwas ist da faul.", sourceObjective = "Verwendet Schnappbolzens Luftanalysegerät, um die Luft zu untersuchen, die 6 stark parfümierte Wachen umgibt, und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Hey, vielen Dank! Gebt her und lasst mal sehen!\n\n<Er nimmt das Gerät an sich und hantiert damit herum.>\n\nOh, das ist gar nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[24541] = { id = 24541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parfümdiebstahl", description = "Ich wusste, dass die was im Schilde führen! Das Zeug enthält irgendeine bewusstseinsverändernde Chemikalie, doch anhand so einer kleinen Probe kann ich nicht ermitteln, was genau es ist. Ich brauch das echte Zeug.\n\nGeht aber nicht einfach rüber und kauft es. Ich will nicht, dass Ihr den Halunken auch nur ein Kupfer gebt. Nein, wir müssen es von der Quelle besorgen, diskret.\n\nIch werde Euch als Lieferbursche verkleiden. Ich hab einen Vorratshaufen gesehen, der von ihren Schlägern bewacht wurde. Geht und lauft dort vorbei, und bleibt NICHT stehen, sonst halten sie Euch auf! Sie werden Euch eine Kiste zuwerfen, bringt diese hierher.", sourceObjective = "Begebt Euch, während Ihr als Lieferbursche verkleidet seid, zum Vorratslager der Chemiemanufaktur Krone vor den Toren Orgrimmars, kehrt dann mit dem Paket, das sie Euch zuwerfen, zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Habt Ihr sie? Gut gemacht! Ganz ausgezeichnet! Mal sehen, was wir hier haben.\n\n<Er öffnet die Kiste und untersucht den Inhalt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24545] = { id = 24545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heiligen und die Verderbten", description = "Ich verwahre mich dagegen, Euch diesen Auftrag zu erteilen, {race}, da er Euch wahrscheinlich ins Verderben führt.\n\nWenn Ihr nichts auf meine Einschätzung gebt und Euch der Aufgabe stellt, werde ich Euch mit dem Wissen und den Ressourcen vertraut machen, die dazu notwendig sind.\n\nIhr müsst in die Frostgramhöhlen zurückkehren und Lichträcher, Arthas' abgelegten Hammer, finden. Neu geschmiedet aus Saronit und geschärft mit dem ätzenden Blut der Monstrositäten des Lichkönigs, wird er die Grundlage unserer Arbeit bilden.", sourceObjective = "Platziert Lichträcher, 25 Einheiten urtümliches Saronit sowie Modermienes und Fauldarms ätzendes Blut in Hochlord Mograines Runenschmiede in der Eiskronenzitadelle.\n\nModermienes ätzendes Blut und Fauldarms ätzendes Blut sind nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle erhältlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[24547] = { id = 24547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Seelenschmaus", description = "Schattenschneide ist eine der besten Waffen, in deren Besitz <ein/eine> {class} kommen kann.\n\nIst Eure Machtgier nun befriedigt, {race}?\n\n<Ihr fühlt Mograines eindringlichen Blick.>\n\nDas dachte ich mir. Dann noch eine letzte Warnung...\n\nNun beginnt der tückischste Teil Eurer Aufgabe. Zügelt Euer Bestreben, denn wenn Eure Ziele nicht rein sind, werdet Ihr Euer Leben, ja, Eure Seele verlieren.\n\nDie Waffe in Euren Händen ist nichts weiter als eine leere Hülle, ein bloßer Schatten dessen, zu was sie werden kann. Allein das Verschlingen von tausend Seelen kann ihre wahren Kräfte freisetzen.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr mit Schattenschneide 1.000 Diener des Lichkönigs in der Eiskronenzitadelle tötet. Die Seelen sind nur in den Schwierigkeitsgraden für 10 oder 25 Mann erhältlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[24548] = { id = 24548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zersplitterte Thron", description = "Der Thron des Lichkönigs war einst sein Gefängnis. Kil'jaeden höchstselbst hat das Behältnis aus Eiskristallen aus dem wirbelnden Nether gefertigt. Sein alleiniger Zweck war es, Ner'zhuls rachsüchtigen Geist festzuhalten.\n\nIndem er den Kristall mit Frostgram berührte, befreite Arthas Ner'zhuls Seele und ließ sie mit seiner eigenen verschmelzen. Die Splitter dieses Zusammenstoßes sind jetzt überall in der Zitadelle verteilt.\n\nIch brauche die Scherben, die wir nur von den mächtigsten Dienern des Lichkönigs bekommen können, um die in Eurer Klinge enthaltene Kraft zu versiegeln.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr 50 Schattenfrostsplitter sammelt.\n\nSchattenfrostsplitter sind nur im Schwierigkeitsgrad für 25 Mann erhältlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[24553] = { id = 24553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt, und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Die Klinge wird sich an Euch binden. Wenn das passiert, tragt sie zu Caladis Prunkspeer in Qel'Delars Ruh.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24554] = { id = 24554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ramponierte Schwertgriff", description = "Dieser ramponierte alte Schwertgriff hat schon bessere Tage gesehen. Bevor er von der Klinge gebrochen wurde, muss es sich dabei um ein wunderschönes Beispiel der Schmiedekunst gehandelt haben.\n\nDie eleganten Symbole und exotischen Edelsteine, die den Griff schmücken, lassen darauf schließen, dass die Waffe womöglich einer mächtigen Person gehörte. Die Sonnenhäscher wären sicherlich am Fund eines solchen Artefakts interessiert. Sucht ihren Repräsentanten in Quel'Delars Ruh südlich des Argentumturnierplatzes auf.", sourceObjective = "Bringt den ramponierten Schwertgriff zu Myralion Sonnenfeuer in Quel'Delars Ruh südlich des Argentumturnierplatzes.", progress = "Was habt Ihr entdeckt?", completion = "<Myralion nimmt den Schwertgriff an sich und inspiziert das Artefakt.>\n\nDas habt Ihr aus der Zitadelle? Was hat es dort gemacht? Diese Klinge ist gewiss kein Erzeugnis der Geißel.\n\nWaffen dieser Qualität können nur von einigen wenigen Geschöpfen Azeroths hergestellt werden. Wir müssen mit ihnen in Verbindung treten und sehen, ob sie uns bei der Identifizierung der Waffe behilflich sein können.", sourceObjectiveStatus = "unverified-source-field" }
quests[24556] = { id = 24556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Verkleidung", description = "Euch ins Innere der Silbernen Enklave zu bringen, wird schwieriger sein, als es erscheint. Nur diejenigen, die über einen Wappenrock des Silberbundes verfügen, wird Zugang zur Zuflucht gewährt. Sollten wir an einen herankommen können, wird eine einfache Verzauberung den Rest erledigen.\n\nAuf dem Balkon über den Fäden des Schicksals werdet Ihr Shandy Lackglanz finden. Ich habe ihm in der Vergangenheit ein paar Mal geholfen - er schuldet mir also noch einen Gefallen. Er kümmert sich um die Wäsche etlicher Leute jeden Schlags aus der Stadt. Vielleicht kann er einen Weg finden, Euch einen Wappenrock eine Weile lang \"auszuleihen\".", sourceObjective = "Besorgt Euch von Shandy Lackglanz einen geliehenen Wappenrock.", progress = "Konnte Shandy Euch helfen, an einen Wappenrock des Silberbunds heranzukommen?", completion = "Ich wusste, dass Shandy einen Weg finden würde. Lasst mich ihn verzaubern, damit Ihr ihn verwenden könnt. Mit etwas Glück wird der Besitzer des Wappenrocks nicht einmal bemerken, dass er verschwunden ist, und Shandy wird unsere Spuren beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24557] = { id = 24557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan des Silberbunds", description = "Einer meiner Kontakte unten in den Kanälen der Schattenseite hat in der Taverne \"Zur Zauberkrähe\" einen Agenten des Silberbunds erblickt. Die Mitglieder des Silberbunds sind normalerweise nicht dafür bekannt, ein Interesse am dortigen Treiben zu hegen, was also sehr stark darauf hindeutet, dass sie etwas vorhaben.\n\nBegebt Euch zur Schattenseite, spürt diesen Agenten auf und schaltet ihn aus. Durchsucht ihn nach allen Informationen, die uns einen Hinweis über den Verbleib dieses Folianten vom Wyrmruhtempel liefern könnten. Wir können nicht zulassen, dass ihn diese albernen Schwächlinge vom Silberbund zuerst zurück nach Eiskrone bringen.", sourceObjective = "Besorgt die Befehle des Silberbunds.", progress = "Konntet Ihr irgendetwas Brauchbares bei diesem Agenten finden?", completion = "<Magister Hathorel liest die erbeuteten Befehle.>\n\nDer Agent, den Ihr abgefangen habt, sollte in der Silbernen Enklave jemanden namens Arkanist Tybalin treffen und dann den Folianten vom Wyrmruhtempel nach Eiskrone bringen. Wie müssen das Buch zurückbekommen, {name}, und es gibt nur eine Möglichkeit, solange es sich noch in der Stadt befindet. Jetzt ist schnelles Handeln gefragt!", sourceObjectiveStatus = "unverified-source-field" }
quests[24558] = { id = 24558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Myralion Sonnenfeuer", description = "Wir müssen dieses Buch zu Myralion Sonnenfeuer bringen. Würdet Ihr das übernehmen? Ich kann diese Aufgabe sonst niemandem anvertrauen, und Ihr habt Geschick darin bewiesen, die Leute vom Silberbund zu meiden.\n\nBringt es nach Quel'Delars Ruh südlich des Argentumturnierplatzes in Eiskrone. Myralion wird Euch dort erwarten. Wenn er die Klinge identifizieren kann, können wir sie im Namen Aethas Sonnenhäschers beanspruchen und Dalaran und der Allianz zeigen, dass wir den Angriff auf den Lichkönig anführen werden.", sourceObjective = "Bringt den Folianten \"Uralte drachengeschmiedete Klingen\" zu Myralion Sonnenfeuer in Quel'Delars Ruh.", progress = "Wir hatten Eure Rückkehr schon erwartet. Was hat Euch aufgehalten?", completion = "<Myralion nimmt das schwere Buch zur Hand und beginnt, darin zu blättern.>\n\nDie Symbole auf der Klinge kamen mir bekannt vor und jetzt weiß ich auch, warum. Das ist zweifellos eine Drachenklinge, die einem der sterblichen Völker zum Geschenk gemacht wurde. Nur um welche Klinge handelt es sich und wie ist sie nach Eiskrone gelangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[24559] = { id = 24559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert neu schmieden", description = "Wir dürfen nicht zulassen, dass Quel'Delar in zerbrochenem und entehrtem Zustand bleibt. Nehmt die Überreste des Schwertes sowie den von Euch gefundenen ramponierten Schwertgriff und begebt Euch in die Grube von Saron in der Eiskronenzitadelle.\n\nIn der Grube lässt der Lichkönig Sklaven Saroniterz fördern sowie be- und verarbeiten. Dieses energieerfüllte Saronit brauchen wir, um Quel'Delar wiederherzustellen.\n\nIhr müsst energieerfüllte Saronitbarren sammeln und den Hammer des Schmiedemeisters erbeuten, Euch mit beidem zum Amboss des Schmiedemeisters begeben und das Schwert neu schmieden.", sourceObjective = "Besorgt 5 energieerfüllte Saronitbarren sowie den Hammer des Schmiedemeisters und verbindet sie mit den Überresten Quel'Delars, um das Schwert wiederherzustellen.", progress = "Konntet Ihr Quel'Delar wiederherstellen?", completion = "Ihr habt die Klinge Quel'Delars wiederhergestellt, der Behauptung Blutkönigin Lana'thels zum Trotz! Jetzt muss die Klinge nur noch getempert werden, bevor wir ihr beweisen können, wie töricht ihre Worte doch waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24560] = { id = 24560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge tempern", description = "Endlich wurden die Bruchstücke von Quel'Delar wieder vereint und die Klinge ist ganz - doch sie muss zuerst getempert werden, bevor Ihr sie einsetzen könnt. Die gezackte Saronitschneide ist spröde und würde beim ersten Kontakt zerbrechen.\n\nIn den Tiefen der Seelenschmiede in der Eiskronenzitadelle gibt es einen Ort, an dem sie sicher getempert werden kann. Nehmt Quel'Delar mit Euch zum Domizil des Verschlingers der Seelen und sucht nach dem Schmelztiegel. Taucht die Klinge dort hinein und bringt sie zurück zu mir in die gefrorenen Hallen.", sourceObjective = "Tempert das neugeschmiedete Quel'Delar im Schmelztiegel der Seelen.", progress = "Solange das Schwert nicht getempert ist, ist es nutzlos.", completion = "Das Tempern des Schwertes sollte die Klinge wiederhergestellt haben. Warum hat es nicht funktioniert?", sourceObjectiveStatus = "unverified-source-field" }
quests[24561] = { id = 24561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen der Reflexion", description = "Ihr habt das Schwert zwar neu geschmiedet und getempert, dennoch ruht es in seiner Scheide und zeigt nichts von der Macht, die es besitzen soll. Ihr sagt, dass es Euch zieht, als hätte es einen eigenen Willen?\n\nWagt Ihr es, das Schwert an den von ihm gewünschten Ort zu bringen? Es ist nicht richtig, dass es so ruhig und doch so hartnäckig ist, und ich fürchte, wir werden nie erfahren weshalb, solltet Ihr es nicht an seinen Zielort bringen. Bringt es in die Hallen der Reflexion in der Eiskronenzitadelle. Seid jedoch auf der Hut! Ich warte in den gefrorenen Hallen auf Euch.", sourceObjective = "Bringt Quel'Delar nach Schwertruh in den Hallen der Reflexion.", progress = "Was ist in den Hallen der Reflexion geschehen?", completion = "Wie kann sich das Böse in solch einem Schwert einnisten? Ich hätte das nicht für möglich gehalten, wenn sich der Beweis nicht direkt vor meinen Augen befände. Wenn die größte Schöpfung der Drachen verdorben und gegen sie gerichtet werden kann, weshalb sollte da ein Schwert die Ausnahme bilden?\n\nIch glaube, Uther hat Recht. Ihr müsst seinem Rat schnell folgen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24562] = { id = 24562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Sonnenbrunnen", description = "Bringt Quel'Delar so schnell wie möglich zum Sonnenbrunnen, {name}! Glaubt Uthers Worten, dass Ihr die Kontrolle über die Klinge nicht immer behalten könnt, wenn sie dem bösen Einfluss des Lichkönigs ausgesetzt ist. Ihr müsst zur Insel von Quel'Danas reisen und versuchen, zum Sonnenbrunnen zu gelangen, um das Schwert zu läutern.\n\nDie Wächter des Sonnenbrunnens werden Euch nicht so einfach Zutritt gewähren. Daher müsst Ihr Euch an Halduron Wolkenglanz wenden, der ein Auge auf die Wachen dort hat.", sourceObjective = "Sprecht mit Halduron Wolkenglanz am Eingang des Sonnenbrunnenplateaus auf der Insel von Quel'Danas.", progress = "Was führt Euch hierher?", completion = "Ich hoffe, Ihr habt Verständnis dafür, dass ich Euch nicht einfach so Zutritt zum Sonnenbrunnen gewähren kann, {name}. Dies ist der heiligste den Sin'dorei bekannte Ort, und wir haben erst kürzlich Kontrolle über ihn zurückerlangt.\n\nIhr wollt unserem Volk mit Märchen über Quel'Delar Hoffnungen machen? Ohne Beweis für die Wahrhaftigkeit Eurer Behauptungen sehe ich keine Veranlassung, Euch Glauben zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24563] = { id = 24563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dämmersucher", description = "Ihr arbeitet mit Myralion Sonnenfeuer zusammen, nicht wahr? Ich weiß, wie wir das Schwert testen können.\n\nWenn Ihr die Geschichte der Klinge kennt, erinnert Ihr Euch vielleicht, dass Thalorien Dämmersucher sie bei der Verteidigung des Sonnenbrunnens gegen die Geißel führte. Er fiel dort, wo sich heute die Todesschneise befindet, und verschaffte so seinen Leuten Zeit, eigene Vorbereitungen zu treffen. Seine sterblichen Überreste befinden sich am südlichen Ende der Todesschneise auf dieser Insel. Begebt Euch dorthin, damit sein Geist Euch den Segen erteilt, zum Sonnenbrunnen zu gehen.", sourceObjective = "Besucht die sterblichen Überreste Thalorien Dämmersuchers und erhaltet seinen Segen für den Gebrauch Quel'Delars.", progress = "Seid Ihr an dem Ort gewesen, an dem Thalorien fiel, als er den Sonnenbrunnen verteidigte?", completion = "Ihr tragt wirklich Quel'Delar bei Euch. Heute ist ein großer Tag für ganz Quel'Thalas und die Sin'dorei! Ihr habt meine Erlaubnis, zum Sonnenbrunnen zu gehen und die Wiederherstellung des Schwertes abzuschließen. Lasst den Kopf nicht hängen, {name}. Die Söhne und Töchter Silbermonds haben viele Jahre auf diesen Tag gewartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24564] = { id = 24564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", progress = "Was ist beim Sonnenbrunnen geschehen?", completion = "Sind meine Augen tatsächlich auf die Waffe Thalorien Dämmersuchers gerichtet? Heute ist ein großer Tag für alle Sonnenhäscher und alle Sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24576] = { id = 24576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine nette Unterhaltung...", description = "<Roka hört widerwillig zu, als Ihr ihr erzählt, warum Ihr versucht, Flenni aufzuspüren.>\n\nIhr meint also, ich hätte die ganze Zeit unter dem Einfluss eines Alchemisten gestanden? Ich kann nicht glauben, dass ich auf diesen Schwindel hereingefallen bin! Wenn ich diesen hinterhältigen Goblin jemals in die Finger kriege, reiß ich ihn in Stücke!\n\nFalls er mit seinen Erledigungen fertig ist, befindet er sich auf dem Weg zum Zeppelinturm östlich der Tore Orgrimmars! Was auch immer Ihr tut, {name}, Ihr dürft ihn nicht an Bord des Zeppelins und davonkommen lassen!\n\nBeeilt Euch, geht zum Zeppelinturm, bevor Ihr ihn verpasst!", sourceObjective = "Begebt Euch zum Zeppelinturm außerhalb Orgrimmars und befragt Flenni Rostrakete zu den Vorräten. Kehrt mit den erhaltenen Informationen zurück.", progress = "Habt Ihr den Kerl gefunden oder hat er sich irgendwo verkrochen?", completion = "Habt Ihr sein Geschäftsbuch bekommen? Wirklich? Das ist wunderbar, {name}! Darin befinden sich bestimmt eine Menge nützlicher Informationen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24579] = { id = 24579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sartharion muss sterben!", description = "Sartharion, der Onyxwächter, hütet die Eier des Zwielichtdrachenschwarms. Er hält sich im Obsidiansanktum in der Kammer der Aspekte unterhalb des Wyrmruhtempels auf.\n\nDer Rat der Sechs hat verfügt, dass Sartharion sterben muss!", sourceObjective = "Tötet Sartharion.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Jetzt, wo Sartharion tot ist, werden Todesschwinges und Sinestras Pläne bestimmt ins Stocken geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24580] = { id = 24580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anub'Rekhan muss sterben!", description = "Anub'Rekhan, einst mächtiger Spinnenfürst im Nerubischen Reich, ist in die Fänge des Lichkönigs geraten, der ihn zu einem Untoten machte.\n\nJetzt fristet er sein Dasein als Gruftlord in seinem Domizil im Arachnidenviertel von Naxxramas und ersinnt Strategien für Kel'Thuzad.\n\nDer Rat der Sechs hat verfügt, dass Anub'Rekhan sterben muss!", sourceObjective = "Tötet Anub'Rhekan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24581] = { id = 24581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth der Seuchenfürst muss sterben!", description = "Noth der Seuchenfürst, Verräter und Feigling! In der Anzahl gegeißelter Seelen folgt er gleich hinter dem Lichkönig selbst.\n\nBegebt Euch schleunigst nach Naxxramas. Dort hält er sich im Seuchenviertel hinter seiner untoten Dienerschaft versteckt.\n\nVernichtet ihn! Der Rat der Sechs hat verfügt, dass Noth sterben muss!", sourceObjective = "Tötet Noth den Seuchenfürst.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Eine Sorge weniger... Jetzt, wo Noth tot ist, wird auch die Forschung der Geißel nach verbesserten Methoden zur Erschaffung Untoter ein Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24582] = { id = 24582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrukteur Razuvious muss sterben!", description = "Instrukteur Razuvious stolziert selbstgefällig durch das Militärviertel von Naxxramas. Man sagt, nur ein von ihm persönlich ausgebildeter Todesritter könne der Macht seiner Klinge standhalten.\n\nIhr und Eure Gruppe sollt das Gegenteil beweisen.\n\nDer Rat der Sechs hat verfügt, dass Razuvious sterben muss!", sourceObjective = "Tötet Instrukteur Razuvious.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24583] = { id = 24583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickwerk muss sterben!", description = "Der sogenannte \"Abgesandte des Krieges\", Flickwerk, ist die ultimative Monstrosität. Außerdem setzt er unseren Truppen in der Drachenöde schwer zu.\n\nIch möchte, dass Ihr Eure Gefährten versammelt und Euch in das Konstruktviertel von Naxxramas begebt, wo Ihr dieses Konstrukt auseinandernehmen sollt.\n\nDer Rat der Sechs hat verfügt, dass Flickwerk sterben muss!", sourceObjective = "Tötet Flickwerk.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Kinder überall auf der Welt werden besser schlafen können, jetzt, da Flickwerk nicht mehr lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24584] = { id = 24584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malygos muss sterben!", description = "Unsere Ressourcen sind erschöpft. Malygos, der Spruchwirker, entzieht der Welt ihre Magie, um sie im Auge der Ewigkeit zu sammeln. Ohne Magie sind wir verloren!\n\n{class}, der Nexuskrieg muss beendet werden. Der Rat der Sechs hat verfügt, dass Malygos sterben muss!", sourceObjective = "Tötet Malygos.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24585] = { id = 24585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flammenleviathan muss sterben!", description = "Auf dem Gestaltungsgelände bildet der Flammenleviathan die erste Verteidigungslinie von Ulduar.\n\nDie Kirin Tor haben die Information erhalten, dass diese vom Bewahrer hergestellte Maschine schon bald an einen unbekannten Ort gebracht und auf die Sterblichen von Azeroth losgelassen werden soll, um Verwüstung über sie zu bringen.\n\nDas dürfen wir nicht zulassen. Der Rat der Sechs hat verfügt, dass der Flammenleviathan sterben muss!", sourceObjective = "Tötet den Flammenleviathan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24586] = { id = 24586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenschuppe muss sterben!", description = "Klingenschuppe bleibt für gewöhnlich in ihrem Horst unweit der Kolossalen Schmiede in Ulduar. Doch kürzlich wurde sie gesehen, wie sie Feuer auf das Land außerhalb des Titankomplexes niederregnen ließ.\n\nZwar hat die Brutmutter eine traurige Vergangenheit, doch stellt sie eine unmittelbare Gefahr für ganz Nordend dar. Der Rat der Sechs hat verfügt, dass Klingenschuppe sterben muss!", sourceObjective = "Tötet Klingenschuppe.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24587] = { id = 24587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignis, Meister des Eisenwerks, muss sterben!", description = "Der große Feuerriese Ignis, Meister des Eisenwerks, schuftet unermüdlich in der Kolossalen Schmiede von Ulduar. Auf Geheiß von Loken stellt Ignis Waffen von schrecklicher Macht her.\n\nDer Rat der Sechs hat verfügt, dass Ignis sterben muss!", sourceObjective = "Tötet Ignis, Meister des Eisenwerks.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Ich gehe davon aus, dass Ihr nicht mit allzu vielen seiner Eisenkonstrukte konfrontiert wart?", sourceObjectiveStatus = "unverified-source-field" }
quests[24588] = { id = 24588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "XT-002 Dekonstruktor muss sterben!", description = "Der XT-002 Dekonstruktor, ein weiteres, seltsames Konstrukt von Mimiron, denkt doch tatsächlich, er wäre der Sohn des Bewahrers! Lasst Euch von seiner geheuchelten Unschuld nicht in die Irre führen, er ist eine todbringende Maschine!\n\nIhr findet den Dekonstruktor auf dem Schrottplatz von Ulduar. Der Rat der Sechs hat verfügt, dass der XT-002 Dekonstruktor sterben muss!", sourceObjective = "Tötet den XT-002 Dekonstruktor.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24589] = { id = 24589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Jaraxxus muss sterben!", description = "Erzmagier Timear hat eine schreckliche Begebenheit vorhergesagt, die sich in Kürze ereignen wird. Ein törichter Gnomenhexenmeister wird während der Prüfung des Kreuzfahrers versehentlich einen Eredarlord der Brennenden Legion heraufbeschwören.\n\nIhr müsst dort sein, wenn es passiert, {class}. Wenn Lord Jaraxxus entkommt, wird er ein Portal öffnen, durch das die Brennende Legion wieder Einzug in unsere Welt erhält.\n\nDer Rat der Sechs hat verfügt, dass Lord Jaraxxus sterben muss!", sourceObjective = "Tötet Lord Jaraxxus.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Ganz Azeroth hatte Glück, dass Timear die Ankunft des Eredarlords vorhergesehen hat und Ihr rechtzeitig dort wart, um ihn zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24590] = { id = 24590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Mark'gar muss sterben!", description = "Lord Mark'gar bewacht den Frostthron in der Bastionskammer. Seit der Lichkönig ihn aus den Knochen Tausender bezwungener Abenteurer zusammengesetzt hat, besitzt Mark'gar selbst die Macht des Thrones.\n\nWenn dieses Knochengespenst nicht vernichtet wird, besteht keine Hoffnung, die Eiskronenzitadelle einzunehmen.\n\nDer Rat der Sechs hat verfügt, dass Lord Mark'gar sterben muss!", sourceObjective = "Tötet Lord Mark'gar.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Dank Euch hat der Frostthron keinen Hauptwächter mehr. Unsere Angriffe auf die Truppen des Lichkönigs werden von nun an von noch größerem Erfolg gekrönt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24594] = { id = 24594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wachen des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24595] = { id = 24595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt, und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Sobald die Klinge wieder hergestellt ist, zeigt sie Caladis Prunkspeer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24596] = { id = 24596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24597] = { id = 24597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den König von Sturmwind", description = "Möchtet Ihr für den König von Sturmwind einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt König Varian Wrynn von Sturmwind einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24598] = { id = 24598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24609] = { id = 24609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Lord von Eisenschmiede", description = "Möchtet Ihr für den Lord von Eisenschmiede einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt König Magni Bronzebart in Eisenschmiede einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
