quests[24615] = { id = 24615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Lordregenten von Quel'Thalas", description = "Möchtet Ihr für den Lordregenten von Quel'Thalas einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Lor'themar Theron in Silbermond einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24629] = { id = 24629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfekter Hauch von Parfüm", description = "Ihr scheint mir voller Tatendrang zu sein, {class}. Was haltet Ihr davon, wenn wir uns zusammen einen Plan ausdenken, aus dem beide Seiten als Gewinner hervorgehen?\n\nDie Manufaktur Krone möchte Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, bekommt Ihr Rabatt auf einige tolle Produkte der Manufaktur Krone.\n\nEure Zeit gegen unser Geld - was sagt Ihr dazu?", sourceObjective = "Besprüht 10 Leute mit dem Parfümzerstäuber der Manufaktur Krone.", progress = "Das Parfüm versprüht sich nicht von selbst, wisst Ihr?\n\nFangt an!", completion = "Großartige Leistung, {name}! Die Leute werden in Scharen kommen, um Parfüms der Manufaktur Krone zu kaufen, jetzt, wo sie ihre Wunder testen konnten.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24635] = { id = 24635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feines Duftwasserwölkchen", description = "Ihr scheint mir Unternehmergeist zu besitzen, {class}. Was haltet Ihr von einem kleinen Geschäft?\n\nDie Manufaktur Krone möchte Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, bekommt Ihr Rabatt auf einige tolle Produkte der Manufaktur Krone.\n\nEure Zeit gegen unser Geld - was sagt Ihr dazu?", sourceObjective = "Besprüht 10 Leute mit dem Duftwasserzerstäuber der Manufaktur Krone.", completion = "Gute Arbeit, {name}! Die Leute werden die Duftwasser der Manufaktur Krone zuhauf kaufen, jetzt, wo sie sie getestet haben.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24636] = { id = 24636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonbonangriff", description = "Ah, ich sehe, dass Ihr Euch keine Gelegenheit entgehen lasst, {class}. Wir könnten zusammen ein wenig Geld machen.\n\nDie Manufaktur Krone muss Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden in der Stadt wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, dürft Ihr auch ein paar tolle Produkte von Manufaktur Krone haben.\n\nEure Zeit gegen unser Geld - kommen wir ins Geschäft?", sourceObjective = "Bewerft 10 Leute mit Schokoladenproben der Manufaktur Krone.", progress = "Wisst Ihr, die Schokolade fliegt nicht von allein zu den Leuten.\n\nIhr müsst anfangen, zu arbeiten!", completion = "Fantastische Leistung, {name}! Die Leute werden sich die Schokolade der Manufaktur Krone gegenseitig aus den Händen reißen, jetzt, wo sie diese süßen, romantischen Leckereien gekostet haben.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24638] = { id = 24638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: im Westen, vor den Toren Orgrimmars. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Lakaien der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport gleich westlich der Tore Orgrimmars in Durotar zu beschädigen und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24645] = { id = 24645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich außerhalb Mühlenberns im Silberwald. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Rohlinge der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb Mühlenberns im Silberwald zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24647] = { id = 24647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich außerhalb des Hügellandhofs im - Ihr habt es erraten - Vorgebirge des Hügellands. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Gauner der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb des Hügellandhofs im Vorgebirge des Hügellands zu zerstören und kehrt zu Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24648] = { id = 24648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in der Nähe der Späherwacht gleich außerhalb Theramores in den Düstermarschen. Jetzt seht mich nicht so an, okay? Das ist auch unser Problem. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Gangster der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb von Theramore in den Düstermarschen zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24649] = { id = 24649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: östlich vom Nistgipfel im Hinterland. Jetzt seht mich nicht so an, okay? Das ist auch ein Problem der Horde. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Agenten der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich des Nistgipfels im Hinterland zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24650] = { id = 24650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in Winterquell, gleich östlich der Ewigen Warte. Oh, jetzt wird's persönlich. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Besprinkler der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich der Ewigen Warte in Winterquell zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24651] = { id = 24651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: scheinbar gleich östlich von Shattrath, in den Wäldern von Terokkar. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Untergebene der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich von Shattrath in den Wäldern von Terokkar zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24652] = { id = 24652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: wie's scheint in den trostlosen Wäldern des Kristallsangwalds, nordwestlich des Zwielichtspiegels. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Sprüher der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport in den trostlosen Wäldern des Kristallsangwalds zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", progress = "Habt Ihr es ihnen gezeigt?", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24655] = { id = 24655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas stinkt hier", description = "Man sieh sich diese Kerle an. Das Dampfdruckkartell betreibt das Valentinstagsgeschäft schon seit Jahren, und plötzlich tauchen diese Typen auf. Die gehören nicht zum Kartell. Das Kartell hat mich beauftragt, der Sache auf den Grund zu gehen. Irgendwas stinkt hier, und damit meine ich nicht das Parfüm.\n\nNehmt das Gerät, das ich mitgebracht habe, um damit die Parfümwolken zu untersuchen, die die Wachen umgeben. Ich möchte wissen, was sie in das Zeug reintun. Irgendwas ist da faul.", sourceObjective = "Verwendet Schnappbolzens Luftanalysegerät, um die Luft zu untersuchen, die 6 stark parfümierte Wachen umgibt, und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", completion = "Hey, vielen Dank! Gebt her und lasst mal sehen!\n\n<Er nimmt das Gerät an sich und hantiert damit herum.>\n\nOh, das ist gar nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[24656] = { id = 24656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parfümdiebstahl", description = "Ich wusste, dass die was im Schilde führen! Das Zeug enthält irgendeine bewusstseinsverändernde Chemikalie, doch anhand so einer kleinen Probe kann ich nicht ermitteln, was genau es ist. Ich brauch das echte Zeug.\n\nGeht aber nicht einfach rüber und kauft es. Ich will nicht, dass Ihr den Halunken auch nur ein Kupfer gebt. Nein, wir müssen es von der Quelle besorgen, diskret.\n\nIch werde Euch als Lieferbursche verkleiden. Ich hab einen Vorratshaufen gesehen, der von ihren Schlägern bewacht wurde. Geht und lauft dort vorbei, und bleibt NICHT stehen, sonst halten sie Euch auf! Sie werden Euch eine Kiste zuwerfen, bringt diese hierher.", sourceObjective = "Begebt Euch, während Ihr als Lieferbursche verkleidet seid, zum Vorratslager der Chemiemanufaktur Krone vor den Toren Sturmwinds, kehrt dann mit dem Paket, das sie Euch zuwerfen, zu Inspektor Snip Schnappbolz in Sturmwind zurück.", progress = "Haben sie Euch eine Kiste zum Ausliefern zugeworfen?", completion = "Habt Ihr sie? Gut gemacht! Ganz ausgezeichnet! Mal sehen, was wir hier haben.\n\n<Er öffnet die Kiste und untersucht den Inhalt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24657] = { id = 24657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine nette Unterhaltung...", description = "<Marion hört erschrocken zu, als Ihr ihr erzählt, warum Ihr versucht, Flenni aufzuspüren.>\n\nIhr meint also, er hätte irgendeine Art Chemikalie auf mich angewandt? Igitt! Ich kann nicht glauben, dass ich auf diesen Schwindel hereingefallen bin!\n\nFalls er mit seinen Erledigungen fertig ist, befindet er sich auf dem Weg zum Dock um ein Schiff in die südlichen Meere zu erwischen! Was auch immer Ihr tut, {name}, Ihr dürft ihn nicht davonkommen lassen!\n\nBeeilt Euch, geht zum Hafen von Sturmwind, bevor Ihr ihn verpasst!", sourceObjective = "Begebt Euch zum Hafen von Sturmwind und befragt Flenni Rostrakete zu den Vorräten. Kehrt mit den erhaltenen Informationen zurück.", progress = "Habt Ihr den Kerl gefunden oder hat er sich irgendwo verkrochen?", completion = "Habt Ihr sein Geschäftsbuch bekommen? Wirklich? Das ist wunderbar, {name}! Darin befinden sich bestimmt eine Menge nützlicher Informationen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24658] = { id = 24658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: nordöstlich der Weststromgarnison im Wald von Elwynn. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Lakaien der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport nordöstlich der Weststromgarnison im Wald von Elwynn zu beschädigen und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24659] = { id = 24659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich südlich des Hains der Uralten in Dunkelküste. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Rohlinge der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport südlich des Hains der Uralten an der Dunkelküste zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
