quests[24664] = { id = 24664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in Winterquell, gleich östlich der Ewigen Warte. Oh, jetzt wird's persönlich. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Besprinkler der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich der Ewigen Warte in Winterquell zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24665] = { id = 24665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: scheinbar gleich östlich von Shattrath, in den Wäldern von Terokkar. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Untergebene der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich von Shattrath in den Wäldern von Terokkar zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24666] = { id = 24666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: wie's scheint in den trostlosen Wäldern des Kristallsangwalds, nordwestlich des Zwielichtspiegels. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Sprüher der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport in den trostlosen Wäldern des Kristallsangwalds zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24682] = { id = 24682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grube von Saron", description = "Schnell, durch das Portal! Ich erwarte Euch auf der anderen Seite.", sourceObjective = "Trefft Fürstin Sylvanas Windläufer am Eingang zur Grube von Saron.", completion = "Unfähige Narren! So langsam frage ich mich, ob sich überhaupt einer von diesen Knilchen vom Turnier als nützlich erweisen wird. Vielleicht könnt Ihr mich ja vom Gegenteil überzeugen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24683] = { id = 24683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grube von Saron", description = "Schnell, durch das Portal! Ich erwarte Euch auf der anderen Seite.", sourceObjective = "Trefft Lady Jaina Prachtmeer in der Grube von Saron.", completion = "Ich habe diesen Geißelfürsten unterschätzt und meine Leute haben dafür bezahlt. Immer, wenn ich denke, dass mich keine größere Schuld mehr an Arthas' Verrat treffen kann, belehrt er mich eines Besseren.\n\nWir müssen weitermachen! Ihr Opfer darf nicht bedeutungslos sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[24710] = { id = 24710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung aus der Grube", description = "Wir müssen den Hauptweg nehmen und durch die Höhle, um zu Tyrannus' Anhöhe zu gelangen. Dort wird er sich uns stellen müssen, wenn er verhindern will, dass wir in die Zitadelle selber gelangen.\n\nGeht jetzt, {class}. Meine Leute und ich werden Euch bei der Konfrontation mit Tyrannus zur Seite stehen.", sourceObjective = "Tötet Geißelfürst Tyrannus.", completion = "Welch sinnlose Verschwendung! Arthas ist zu weit gegangen! Ich hoffe nur, dass das, was wir in den Hallen der Reflexion vorfinden werden, all das wert ist.\n\nWenn man den Worten dieses abscheulichen Gnoms trauen kann, sollten sich dort Frostgram und damit auch Antworten auf die Frage befinden, wie Arthas zu begegnen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24711] = { id = 24711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostgram", description = "Wir müssen weiter! Wir sind schon so weit gekommen... wir sind unserem Ziel ganz nah. Ich muss Euch kurz verlassen und Elandra zum Luftschiff zurückschicken. Ich weiß nicht genau, wie wir fliehen sollen, wo wir so viele Leute verloren haben und nur noch wenige übrig sind, die unseren Pfad sichern. Wir brauchen jede Hilfe, die wir kriegen können!\n\nMacht weiter, ich erwarte Euch in den Hallen der Reflexion.", sourceObjective = "Trefft Lady Jaina Prachtmeer am Eingang zu den Hallen der Reflexion.", completion = "Die Hallen der Reflexion, endlich!\n\nLasst mich wissen, wenn Ihr bereit seid. Arthas ist zwar nicht hier, aber es wäre naiv, zu glauben, er ließe Frostgram vollkommen unbewacht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24712] = { id = 24712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung aus der Grube", description = "Wir müssen den Hauptweg nehmen und durch die Höhle, um zu Tyrannus' Anhöhe zu gelangen. Dort wird er sich uns stellen müssen, wenn er verhindern will, dass wir in die Zitadelle selber gelangen.\n\nGeht jetzt, {class}. Meine Leute und ich werden Euch bei der Konfrontation mit Tyrannus zur Seite stehen.", sourceObjective = "Tötet Geißelfürst Tyrannus.", completion = "Die Hallen der Reflexion liegen vor uns. Wenn man den Worten dieses abscheulichen Gnoms trauen kann, sollten sich dort Frostgram und damit auch Antworten auf die Frage befinden, wie Arthas zu begegnen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24713] = { id = 24713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostgram", description = "Macht weiter, wir sind dem Schwert ganz nahe.\n\nIch brauche einen Augenblick, um eine meiner Dunklen Waldläuferinnen zurück zum Luftschiff zu schicken. Jetzt, wo wir keine Unterstützung mehr haben, müssen Vorkehrungen getroffen werden. Wir brauchen jede Hilfe, die wir kriegen können!\n\nGeht, ich erwarte Euch in den Hallen der Reflexion.", sourceObjective = "Trefft Fürstin Sylvanas Windläufer am Eingang zu den Hallen der Reflexion.", completion = "Die Hallen der Reflexion, endlich!\n\nLasst mich wissen, wenn Ihr bereit seid, {class}. Ich werde nicht so naiv sein, zu glauben, dass Arthas sein wertvolles Schwert vollkommen unbewacht zurückgelassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[24743] = { id = 24743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschneide" }
quests[24745] = { id = 24745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas liegt in der Luft (und Liebe ist es nicht)", description = "Auf die Innenseite der Karte sind verrückte, detaillierte Pläne gekritzelt, einen Großteil Azeroths zu infizieren. Das müsst Ihr sofort einem der Ermittler des Dampfdruckkartells zeigen!", sourceObjective = "Bringt die vergilbte schöne Grußkarte zu Inspektor Snip Schnappbolz in Sturmwind.", progress = "Habt Ihr Euch um diese nichtsnutzigen, Ränke schmiedenden Gauner gekümmert?", completion = "Was habt Ihr denn da?\n\nUi, das ist groß! Riesig! So viele verrückte Details auf einem Haufen! Danke, Ihr habt uns wirklich sehr geholfen. Mit Euch kann man wirklich gut zusammenarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24749] = { id = 24749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit unheiliger Macht", description = "Bevor Eure Waffe ihre volle Kraft entfalten kann, muss sie mit den für sie charakteristischen Kräften ausgestattet werden. Die erste davon ist Unheiligkeit.\n\nIhr müsst jemanden namens Professor Seuchenmord ausfindig machen und töten, doch das ist noch nicht alles. Ihr müsst seine eigenen Mittel und Methoden gegen ihn verwenden.\n\nFindet einen Weg, seinen mutierten Schleim zu absorbieren. Benutzt die stinkende Substanz, um Eure Waffe mit unheiliger Macht zu erfüllen. Erst dann sollt Ihr Eure nächste Aufgabe von mir erhalten.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr Schattenschneide mit unheiliger Macht erfüllt und Professor Seuchenmord tötet.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24756] = { id = 24756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit der Macht des Blutes", description = "Nun kann Eure Waffe mit der Macht des Blutes versehen werden.\n\nIhr müsst gegen Blutkönigin Lana'thel kämpfen und Euch ihrem Blutspiegel aussetzen. Durch diese Macht wird Schattenschneide das Blut des nächstgelegenen Lebewesens trinken. Das wäret dann Ihr, {race}.\n\nLasst, sobald die Klinge erwacht ist, den rasenden Blutdurst der Königin über Euch kommen, gebt Euch ihm hin und bereitet ihr einen schmachvollen Tod.\n\nMögen ihre Schreie in den Ohren des Lichkönigs schmerzen, während er auf sein Schicksal wartet!", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr Schattenschneide mit der Macht des Blutes erfüllt und Blutkönigin Lana'thel besiegt.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24757] = { id = 24757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit der Macht des Frostes", description = "Nun ist Schattenschneide bereit, mit der letzten Macht erfüllt werden.\n\nSindragosa, das persönliche Reittier des Feindes, muss fallen! Doch bevor Ihr sie tötet, müsst Ihr ihrer Frostatemattacke viermal widerstehen ohne zu sterben.\n\nIst der Drache erst einmal beseitigt, steht nichts mehr zwischen Euch und dem Lichkönig.", sourceObjective = "Hochlord Darion Mograine hat Euch den Auftrag erteilt, Sindragosa zu töten, nachdem Ihr 4-mal ihren Atemattacken ausgesetzt wart, während Ihr Schattenschneide führt.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24788] = { id = 24788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher, zufälliger heroischer Dungeon (Erster)" }
