quests[24790] = { id = 24790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher, zufälliger normaler Dungeon (Erster)" }
quests[24791] = { id = 24791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher, zufälliger normaler Dungeon (Nter)" }
quests[24792] = { id = 24792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insider", description = "Ihr wirkt, als könntet Ihr Euch nun um den Strippenzieher all dessen kümmern. In dem Geschäftsbuch steht, er hätte sich auf Burg Schattenfang verkrochen. Dorthin sollt Ihr Euch begeben.\n\nEiner unserer Leute befindet sich bereits vor Ort, doch er selbst kann nichts unternehmen. Geht jetzt, der Ermittler erwartet Euch. Und nehmt ein paar Freunde mit.", sourceObjective = "Meldet Euch bei Ermittler Fezzen Kupferstapel auf Burg Schattenfang.", completion = "Fantastisch! Hilfe kann ich wirklich gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24793] = { id = 24793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insider", description = "Ihr wirkt, als könntet Ihr Euch nun um den Strippenzieher all dessen kümmern. In dem Geschäftsbuch steht, er hätte sich auf Burg Schattenfang verkrochen. Dorthin sollt Ihr Euch begeben.\n\nEiner unserer Leute befindet sich bereits vor Ort, doch er selbst kann nichts unternehmen. Geht jetzt, der Ermittler erwartet Euch. Und nehmt ein paar Freunde mit.", sourceObjective = "Meldet Euch bei Ermittler Fezzen Kupferstapel auf Burg Schattenfang.", completion = "Fantastisch! Hilfe kann ich wirklich gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24795] = { id = 24795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für den Silberbund", description = "Trotz der Angeberei Königin Lana'thels habt Ihr Quel'Delar wiederhergestellt, {name}. Wie lange haben wir davon geträumt, Quel'Delar wieder an uns zu nehmen.\n\nNicht nur der Silberbund, sondern alle Quel'dorei schulden Euch ihren Dank.\n\nDas Schwert scheint zu wissen, dass Ihr als {class} nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Vielleicht kann der Argentumkreuzzug helfen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen des Silberbundes an Justiziarin Mariel Treuherz.", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[24796] = { id = 24796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für den Silberbund", description = "Trotz der Angeberei Königin Lana'thels habt Ihr Quel'Delar wiederhergestellt, {name}. Wie lange haben wir davon geträumt, Quel'Delar wieder an uns zu nehmen.\n\nNicht nur der Silberbund, sondern alle Quel'dorei schulden Euch ihren Dank.\n\nVereesa Windläufer, die Anführerin des Silberbundes, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, wo sie auf Euch wartet, {name}.", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Vereesa Windläufer in der Violetten Zitadelle in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[24797] = { id = 24797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24798] = { id = 24798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Sonnenhäscher", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Sin'dorei wiederhergestellt!\n\nGanz Silbermond wird Euch als Helden feiern, {name}.\n\nDas Schwert scheint zu wissen, dass Ihr als {class} nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Noch hat sich kein würdiger Sin'dorei gemeldet. Lasst uns den Rat des Argentumkreuzzugs suchen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen der Sonnenhäscher an Justiziarin Mariel Treuherz.", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[24799] = { id = 24799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Sonnenhäscher", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher wiederhergestellt!\n\nDie gesamte Horde wird Euch als Helden feiern, {name}.\n\nDas Schwert scheint zu wissen, dass Ihr als {class} nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Ich kann meine Enttäuschung nicht verbergen... ich hatte gehofft, es würde ein würdiger Sin'dorei sein. Lasst uns den Rat des Argentumkreuzzugs suchen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen der Sonnenhäscher an Justiziarin Mariel Treuherz.", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[24800] = { id = 24800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Sonnenhäscher", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Sin'dorei wiederhergestellt!\n\nGanz Silbermond wird Euch als Helden feiern, ebenso wie die gesamte Horde, {name}.\n\nDer Erzmagier Aethas Sonnenhäscher, der Anführer der Sonnenhäscher, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, {name}. Der Erzmagier will Euch persönlich gratulieren!", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Erzmagier Aethas Sonnenhäscher in der Violetten Zitadelle in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[24801] = { id = 24801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Sonnenhäscher", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Horde wiederhergestellt!\n\nDies ist ein wahrer Segen für unsere Bemühungen gegen den Lichkönig.\n\nDer Erzmagier Aethas Sonnenhäscher, der Anführer der Sonnenhäscher, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, {name}. Der Erzmagier will Euch persönlich gratulieren!", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Erzmagier Aethas Sonnenhäscher in der Violetten Zitadelle in Dalaran.", progress = "Ist es wahr, dass Ihr Quel'Delar wiederhergestellt habt?", completion = "Quel'Delar erhebt sich von neuem, so wie wir Sin'dorei uns aus der Asche der Niederlage und des Verrats erhoben haben. Und dennoch hat sich die Waffe Thalorien Dämmersuchers aus irgendeinem Grunde entschieden, einem Außenseiter zu dienen.\n\nBeruhigt Euch, {name}. Ich gedenke nicht, Eure Errungenschaft zu schmälern, da Ihr etwas vollbracht habt, was keiner meiner Brüder vermocht hat, obschon ich nicht weiß, wie Ihr es angestellt habt. Ihr seid eindeutig dazu ausersehen, sein Träger zu sein... die Klinge hat bereits begonnen, sich an Eure Stärken anzupassen. Tragt Quel'Delar mit Stolz im Kampf gegen unsere Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[24802] = { id = 24802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Lichkönigs", description = "Uther wusste viel darüber, wie Arthas möglicherweise zu schlagen ist. Es besteht wohl kaum Hoffnung, Arthas auf den Stufen seines eigenen Thrones zu besiegen. Und wer übernimmt in diesem Fall die Krone des Lichkönigs?\n\nViele Fragen sind noch offen, doch die von Euch gelieferten Antworten könnten ausschlaggebend für einen Sieg über Arthas sein. Ihr müsst Sylvanas finden und vor dem Lichkönig fliehen, so lange Zeit dazu ist.", sourceObjective = "Findet Lady Sylvanas Windläufer und flieht aus den Hallen der Reflexion.", completion = "Und wieder schlüpft mir die Rache durch die Finger. Es ist schwer zu glauben, wie viel stärker er geworden ist.\n\nEs war töricht von Euch, wegen mir herzukommen, aber dennoch ist es gut zu wissen, dass es immer noch einige Champions der Horde gibt, die keine nutzlosen Feiglinge sind. Die Informationen, die Uther uns gab, mögen wohl der Schlüssel dafür sein, Arthas endlich zu besiegen, aber es wird immer deutlicher, dass die Horde dies nicht allein wird bewerkstelligen können.\n\nGeht, {class}. Ich gehe davon aus, dass Eure Fähigkeiten bald wieder gebraucht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24803] = { id = 24803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelwettstreit der Kalu'ak" }
quests[24804] = { id = 24804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliche Düfte", description = "Irgend etwas stimmt nicht mit dieser Chemiemanufaktur Krone. Dampfdruck hat ein Auge darauf geworfen, aber wir könnten noch ein paar mehr gebrauchen.\n\nBegebt Euch nach Sturmwind, wenn Ihr uns helfen wollt. Inspektor Snip Schnappbolz leitet die Untersuchung dort und er kann jede Hilfe gebrauchen, die er kriegen kann.", sourceObjective = "Meldet Euch bei Inspektor Snip Schnappbolz in Sturmwind.", completion = "Hey, habt Ihr etwas Zeit mitgebracht? Ich könnte jemanden wie Euch gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24805] = { id = 24805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliche Düfte", description = "Irgend etwas stimmt nicht mit dieser Chemiemanufaktur Krone. Dampfdruck hat ein Auge darauf geworfen, aber wir könnten noch ein paar mehr gebrauchen.\n\nBegebt Euch nach Orgrimmar, wenn Ihr uns helfen wollt. Detektiv Snap Schnappbolz leitet die Untersuchung dort und er kann jede Hilfe gebrauchen, die er kriegen kann.", sourceObjective = "Meldet Euch bei Detektiv Snap Schnappbolz in Orgrimmar.", completion = "Hey, habt Ihr etwas Zeit mitgebracht? Ich könnte jemanden wie Euch gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24806] = { id = 24806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Glück beim nächsten Mal" }
quests[24815] = { id = 24815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Euren Weg", sourceObjective = "Um für die Sünden, die ich als Ritter des Lichkönigs begangen habe, Sühne zu leisten, habe ich mich der Herstellung von Ringen der Macht für unsere Brüder und Schwestern verschrieben, die sie in der Schlacht verwenden können.\n\nIhr habt Euch beim Kampf gegen die Geißel als wertvoller Verbündeter erwiesen, {name}. Wenn Eure Hingabe weiter fortbesteht, kann ich den ursprünglichen Entwurf des Rings verbessern.\n\nWählt Euren Weg mit Bedacht. Ein Sinneswandel wird seinen Preis kosten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24819] = { id = 24819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[24820] = { id = 24820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[24821] = { id = 24821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel", progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, {name}?", completion = "Möget Ihr finden, wonach Ihr suchet, Bruder." }
quests[24822] = { id = 24822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[24823] = { id = 24823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Zerstörung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
