quests[24829] = { id = 24829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Zerstörung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nDer Feind spricht Euren Namen nur flüsternd aus, denn er weiß, dass Ihr eine Macht seid, mit der er rechnen muss.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
