quests[24835] = { id = 24835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Mutes", progress = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nIhr seid eine Quelle der Inspiration für unsere Verbündeten und Euer unerschütterlicher Mut lässt selbst die erfahrensten Generäle des Feindes innehalten.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
