quests[24848] = { id = 24848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerwerk bei der Güldenen Rose", description = "Kind, hier geht es um mehr als bloß Parfüm. In dieser Kiste waren ein paar Raketen und sie sind mit irgend einer chemischen Ladung gefüllt. Hier kann ich sie nicht analysieren, aber ich werde Euch den Weg ins Labor ersparen.\n\nIhr müsst nur den Typ aufspüren, der sie hergestellt hat. Ich kenne das Brandzeichen. Flenni Rostrakete.\n\nIch habe einen Tipp von einer vertrauenswürdigen Quelle erhalten, dass er sich hier in Sturmwind aufhält und es sich in der Güldenen Rose gut gehen lässt. Er soll sogar eine Dame bei sich haben, mit Namen Marion Sutton. Macht Euch auf zur Güldenen Rose und findet heraus, was sie weiß.", sourceObjective = "Redet mit Marion Sutton in der Güldenen Rose im Handelsdistrikt von Sturmwind.", completion = "Ihr... Ihr seid nicht Flenni. Hat er Euch geschickt? Er ist so spät dran, ich hatte schon die Hoffnung aufgegeben...\n\n<Tränen schimmern in ihren Augen, als sie begreift, dass Ihr nicht dort seid, um eine Nachricht von Flenni zu überbringen.>\n\nDas passt gar nicht zu meinem Flenni, aber was für eine andere Möglichkeit gibt es?", sourceObjectiveStatus = "unverified-source-field" }
quests[24849] = { id = 24849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Fersen", description = "Ich fange am besten von vorne an. Es war Liebe auf den ersten Blick, {name}. Da war einfach etwas Besonderes an diesem Goblin, schon als meine Augen ihn das erste Mal erblickten.\n\nNachdem wir eine wundervolle Woche miteinander verbracht hatten, meinte Flenni, dass er an eine Menge Geld gekommen sei und mich auf eine Reise in die Südlichen Meere mitnehmen wolle! Könnt Ihr Euch das vorstellen?\n\nWie auch immer, er meinte, ich solle meine Sachen packen, während er noch zur Bank, zum Auktionshaus und zum Barbier müsse. Aber er ist nie wieder aufgetaucht! Ich fange langsam an zu glauben, dass er einfach nur ein großer Lügner ist!", sourceObjective = "Sucht Flenni Rostrakete im Zählhaus von Sturmwind, im Auktionshaus und beim Barbier von Sturmwind.", completion = "Er hat also nur davon gesprochen, dass er die Stadt mit all seinem Geld verlassen will? Dann hat er mich wirklich sitzen lassen, oder?\n\nOh, was war ich bescheuert, mich in ihn zu verlieben, aber wie hätte ich es verhindern können? Er war so unwiderstehlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[24850] = { id = 24850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flennis Flamme", description = "Kind, hier geht es um mehr als bloß Parfüm. In dieser Kiste waren ein paar Raketen und sie sind mit irgend einer chemischen Ladung gefüllt. Hier kann ich sie nicht analysieren, aber ich werde Euch den Weg ins Labor ersparen.\n\nIhr müsst nur den Typ aufspüren, der sie hergestellt hat. Ich kenne das Brandzeichen. Flenni Rostrakete.\n\nIch habe gehört, dass er es sich hier in Orgrimmar gut gehen lässt. Und es kommt noch besser, er soll sogar eine Freundin haben... eine Orc-Dame mit Namen Roka. Sie will sich mit ihm bei Gotris Reiseausstattung in der Gasse treffen, bevor sie ihre Flucht antreten.", sourceObjective = "Redet mit Roka bei Gotris Reiseausstattung in der Gasse in Orgrimmar.", completion = "Ihr seid nicht Flenni. Er hätte schon vor einer Stunde hier sein sollen! Was habt Ihr mit ihm angestellt?\n\n<Roka scheint sich zu beruhigen, als Ihr ihr erklärt, dass Ihr selber nach Flenni sucht. Dann schimmern Tränen in ihren Augen.>\n\nDas sieht meinem süßen Flenni gar nicht ähnlich. Meint Ihr, ihm ist etwas zugestoßen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24851] = { id = 24851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Fersen", description = "Ich fange am besten von vorne an. Es war Liebe auf den ersten Blick, {name}. Da war einfach etwas Besonderes an diesem Goblin, schon als meine Augen ihn das erste Mal erblickten.\n\nNachdem wir eine wundervolle Woche miteinander verbracht hatten, meinte Flenni, dass er an eine Menge Geld gekommen sei und mich auf eine Reise in die Südlichen Meere mitnehmen wolle! Könnt Ihr Euch das vorstellen?\n\nWie auch immer, er meinte, ich solle meine Sachen packen, während er noch zur Bank, zum Auktionshaus und zum Barbier müsse. Aber er ist nie wieder aufgetaucht! Ich fange langsam an zu glauben, dass er einfach nur ein großer Lügner ist!", sourceObjective = "Sucht Flenni Rostrakete in der Bank von Orgrimmar, dem Auktionshaus und dem Barbier von Orgrimmar.", completion = "Er hat also nur davon gesprochen, dass er die Stadt mit all seinem Geld verlassen will? Dann hat er mich wirklich sitzen lassen, oder?\n\nIch kann nicht glauben, dass ich auf einen so schrecklichen Goblin reingefallen bin! Aber er war so unwiderstehlich, als wir uns das erste Mal sahen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24857] = { id = 24857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Camp Narache", description = "Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Ihr die Pläne für eine ausgeweitete Belagerung von Camp Narache entdeckt habt, die von dem Kriegshäuptling der Borstennacken entworfen wurden.\n\nHäuptling Falkenwind kann mit dieser Information sicher einiges anfangen!", sourceObjective = "Bringt die Angriffspläne der Borstennacken zu Häuptling Falkenwind in Camp Narache.", progress = "Ihr seht besorgt aus, {name}. Welche Neuigkeiten bringt Ihr mir?", completion = "Das ist in der Tat ziemlich alarmierend! Aber mit dieser Information können wir unseren Brüdern im Dorf der Bluthufe Bescheid geben, dass sie uns helfen den Angriff abzuwenden. Ihr habt das Leben vieler {race} gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24869] = { id = 24869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entprogrammieren", description = "Wir hatten gehofft, einen Mann in den Reihen des Kults der Verdammten platzieren zu können, um einen besseren Eindruck von den Machenschaften des Lichkönigs zu bekommen, aber wir... haben die Überredungskünste von Arthas und seiner dunklen Gesandten, Lady Todeswisper, unterschätzt.\n\nUnser Mann, Darnavan, ist jetzt einer von ihnen.\n\nWenn Ihr vorhabt, Euch einen Weg durch das Oratorium vor uns zu bahnen, so haltet Eure Augen bitte nach Darnavan auf. Wenn Ihr ihn uns lebend übergeben könntet, könnten wir versuchen, die Hirnwäsche des Kults rückgängig zu machen.", sourceObjective = "Bezwingt Lady Todeswisper, aber stellt dabei sicher, dass Darnavan überlebt.", completion = "Danke Euch, {name}!\n\nIch schulde Euch großen Dank dafür, dass Ihr einen Freund gerettet habt, den ich schon für verloren in den Klauen des Kults gehalten habe. Und der Argentumkreuzzug schuldet Euch Dank für die unschätzbaren Informationen, die Darnavan durch seine Zeit als Anhänger des Kults in den Hallen der Zitadelle gesammelt hat.\n\nBitte, nehmt dies als Zeichen unserer Anerkennnung, und möge Euch das Licht stärken, wenn Ihr eine Schneise durch diesen schrecklichen Ort pflügt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24870] = { id = 24870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Bollwerks", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Allianzhunde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", sourceObjective = "Erledigt den verrottenden Frostriesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24871] = { id = 24871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Bollwerks", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Hunde von der Horde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", sourceObjective = "Erledigt den verrottenden Frostriesen.", completion = "Der Riese ist tot? Gepriesen sei das Licht!\n\nDer Weg voraus und hinauf ist nun frei. Nehmt einige dieser Beutestücke als Zeichen unserer Dankbarkeit, und sobald der Frostthron dem Erdboden gleichgemacht ist, stoßen wir gemeinsam an!", sourceObjectiveStatus = "unverified-source-field" }
quests[24872] = { id = 24872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frieden für eine geschundene Seele", description = "Nehmt diesen Kristall des Lebens, und auch Eure Gefährten sollten einen nehmen. Er enthält mächtige Energien aus dem tiefgrünen Drachenschrein in der Drachenöde, und es war mein eigenes Geheimnis, um den dunklen Magien dieses Ortes so lange widerstehen zu können.\n\nWenn Ihr Sindragosa gegenübertretet, bekämpft sie, bis sie geschwächt ist, und dann sollten Eure Gefährten diese Kristalle benutzen, um die Essenz herauszulocken, die in ihr schläft. Wenn Ihr sie dann besiegt, solltet Ihr in der Lage sein, die Essenz aufzunehmen und zum Wyrmruhtempel in der Drachenöde zurückzubringen.", sourceObjective = "Benutzt die Lebenskristall, um Sindragosas Essenz zu erhalten.", progress = "Was haltet Ihr da in Händen, Sterblicher?", completion = "<Kalecgos seufzt>\n\nSo viel Leid, so viel sinnlose Zerstörung. Dies waren keine guten Zeiten für meine Brüder und Schwestern. Aber dank Eurer Anstrengungen, tapfere Abenteurer, kann diese befleckte, aber immer noch edle Seele endlich Frieden finden.\n\nRuhet nun, Sindragosa. Ihr seid zuhause...", sourceObjectiveStatus = "unverified-source-field" }
quests[24873] = { id = 24873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelnder Wirt", description = "Professor Seuchenmord ist in sein fauliges Labor eingeschlossen worden, wo er immer tödlichere Kulturen der Seuche gegen uns entwickelt. Wenn wir nur einige reine Proben dieser Gifte in die Finger bekommen könnten, dann könnten unsere Forscher ein Antidot enwickeln und unzählige Leben retten.\n\nEs gibt nur einen Haken... eine nützliche Probe müsste aus zwei aktiven Stämmen bestehen, die sich in einem lebenden Wirt verbinden. Sollte Euch das... Missgeschick... widerfahren, solch ein Wirt zu werden, dann kommt bitte sofort hier her, sodass wir Euch für unsere Studien abernten können.", sourceObjective = "Kehrt zu Alchemistin Adrianna zurück, während Ihr mit der orangenen und der grünen Seuche infiziert seid.", completion = "Endlich können wir lebende Exemplare studieren. Ihr habt heute dabei geholfen, unzählige Leben zu retten, {name}!\n\nBitte, nehmt dies als Zeichen unserer Dankbarkeit für Eure Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[24874] = { id = 24874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhöhter Blutdruck", description = "Diese Geißel-Blutsauger - San'layn nennen sie sich - sind mir nicht geheuer. Wir haben einen unserer besten Männer eingesetzt, um ein Auge auf sie zu halten. Aber diesen Morgen ist er unvorsichtig geworden und hat sich erwischen lassen. Er wird gerade von der Königin persönlich verhört, und seine Schreie gellen durch die Blutroten Hallen. Bitte, rettet ihn, bevor es zu spät ist.", sourceObjective = "Rettet den Spitzel Minchar, bevor er hingerichtet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[24875] = { id = 24875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entprogrammieren", description = "Wir hatten gehofft, einen Mann in den Reihen des Kults der Verdammten platzieren zu können, um einen besseren Eindruck von den Machenschaften des Lichkönigs zu bekommen, aber wir... haben die Überredungskünste von Arthas und seiner dunklen Gesandten, Lady Todeswisper, unterschätzt.\n\nUnser Mann, Darnavan, ist jetzt einer von ihnen.\n\nWenn Ihr vorhabt, Euch einen Weg durch das Oratorium vor uns zu bahnen, so haltet Eure Augen bitte nach Darnavan auf. Wenn Ihr ihn uns lebend übergeben könntet, könnten wir versuchen, die Hirnwäsche des Kults rückgängig zu machen.", sourceObjective = "Bezwingt Lady Todeswisper, aber stellt dabei sicher, dass Darnavan überlebt.", completion = "Danke Euch, {name}!\n\nIch schulde Euch großen Dank dafür, dass Ihr einen Freund gerettet habt, den ich schon für verloren in den Klauen des Kults gehalten habe. Und der Argentumkreuzzug schuldet Euch Dank für die unschätzbaren Informationen, die Darnavan durch seine Zeit als Anhänger des Kults in den Hallen der Zitadelle gesammelt hat.\n\nBitte, nehmt dies als Zeichen unserer Anerkennnung, und möge Euch das Licht stärken, wenn Ihr eine Schneise durch diesen schrecklichen Ort pflügt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24876] = { id = 24876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Bollwerks", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Hunde von der Horde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", sourceObjective = "Erledigt den verrottenden Frostriesen.", progress = "Ist der Riese tot?", completion = "Der Riese ist tot? Gepriesen sei das Licht!\n\nDer Weg voraus und hinauf ist nun frei. Nehmt einige dieser Beutestücke als Zeichen unserer Dankbarkeit, und sobald der Frostthron dem Erdboden gleichgemacht ist, stoßen wir gemeinsam an!", sourceObjectiveStatus = "unverified-source-field" }
quests[24877] = { id = 24877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Bollwerks", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Allianzhunde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", sourceObjective = "Erledigt den verrottenden Frostriesen.", progress = "Ist der Riese tot?", completion = "Der Riese ist tot? Für die Horde!\n\nDer Weg voraus und hinauf ist nun frei. Nehmt einige dieser Beutestücke als Zeichen unserer Dankbarkeit, und sobald der Frostthron dem Erdboden gleichgemacht ist, stoßen wir gemeinsam an!", sourceObjectiveStatus = "unverified-source-field" }
quests[24878] = { id = 24878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelnder Wirt", description = "Professor Seuchenmord ist in sein fauliges Labor eingeschlossen worden, wo er immer tödlichere Kulturen der Seuche gegen uns entwickelt. Wenn wir nur einige reine Proben dieser Gifte in die Finger bekommen könnten, dann könnten unsere Forscher ein Antidot enwickeln und unzählige Leben retten.\n\nSolltet Ihr zufällig über ein lebendiges Exemplar stolpern, so bringt es bitte sofort hierher, damit wir es analysieren können.", sourceObjective = "Kehrt zu Alchemistin Adrianna zurück, während Ihr mit der orangenen und der grünen Seuche infiziert seid.", completion = "Endlich können wir lebende Exemplare studieren Ihr habt heute dabei geholfen, unzählige Leben zu retten, {name}!\n\nBitte, nehmt dies als Zeichen unserer Dankbarkeit für Eure Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[24879] = { id = 24879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhöhter Blutdruck", description = "Diese Geißel-Blutsauger - San'layn nennen sie sich - sind mir nicht geheuer. Wir haben einen unserer besten Männer eingesetzt, um ein Auge auf sie zu halten. Aber diesen Morgen ist er unvorsichtig geworden und hat sich erwischen lassen. Er wird gerade von der Königin persönlich verhört, und seine Schreie gellen durch die Blutroten Hallen. Bitte, rettet ihn, bevor es zu spät ist.", sourceObjective = "Rettet den Spitzel Minchar, bevor er hingerichtet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[24880] = { id = 24880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frieden für eine geschundene Seele", description = "Nehmt diesen Kristall des Lebens, und auch Eure Gefährten sollten einen nehmen. Er enthält mächtige Energien aus dem tiefgrünen Drachenschrein in der Drachenöde, und es war mein eigenes Geheimnis, um den dunklen Magien dieses Ortes so lange widerstehen zu können.\n\nWenn Ihr Sindragosa gegenübertretet, bekämpft sie, bis sie geschwächt ist, und dann sollten Eure Gefährten diese Kristalle benutzen, um die Essenz herauszulocken, die in ihr schläft. Wenn Ihr sie dann besiegt, solltet Ihr in der Lage sein, die Essenz aufzunehmen und zum Wyrmruhtempel in der Drachenöde zurückzubringen.", sourceObjective = "Benutzt die Lebenskristall, um Sindragosas Essenz zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24881] = { id = 24881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zufälliger, klassischer Dungeon 5-15 (Erster)" }
