quests[25306] = { id = 25306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid jetzt in der Gnarmee!" }
quests[25444] = { id = 25444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekten Spione", description = "Es wär dumm, hia blind zu arbeiten, also mach' ich 'n paar winzige Spione, die für Vol'jin Informationen sammeln soll'n. Er muss wissen, was drüben auf den Inseln passiat.\n\nIch könnt' die Hilfe brauch'n, wenn Euch danach is. Ich sag' Euch, was zu tun is. East müsst Iah die Frösche fang'n. Sie bleim gean im Schatten dea Palmen um Sen'jin rum.\n\nWenn Iah die Frösche habt, bringtse hia rüber zu mei'm Totem des Wachens un' stimmt se auf meine Sicht ab.", sourceObjective = "Fangt 5 Frösche aus Sen'jin und stimmt sie bei Vaniras Totem des Wachens auf ihre Sicht ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[25482] = { id = 25482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Headless Horseman" }
quests[25483] = { id = 25483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Coren Direbrew" }
quests[25484] = { id = 25484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Ahune" }
quests[25485] = { id = 25485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Hummel" }
quests[63448] = { id = 63448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Deluxelieferung", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63450] = { id = 63450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Deluxelieferung", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[63767] = { id = 63767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtel in der Kugel", sourceObjective = "Grüße, {class}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63768] = { id = 63768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtel in der Kugel", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnung im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diesen Gegenstand jemals verlieren, kommt zu mir zurück, und ich ersetze ihn Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[63770] = { id = 63770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Dank" }
quests[63865] = { id = 63865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Dank", sourceObjective = "Grüße, {name},\n\nHier ist ein besonderes Geschenk für Euch als passionierten Sammler! Wir möchten Euch diesen kleinen aber aufgeweckten Freund überreichen. Möge er Euch zu neuen Abenteuern auf der anderen Seite des Dunklen Portals in der Scherbenwelt führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[63866] = { id = 63866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beherrschung des Lichts", description = "Nehmt dieses Gefäß, {name}. Seine Magie wird es Euch erlauben, die Macht dieser Kreatur an Euch zu nehmen. Mit ihr werdet Ihr in der Lage sein, Euren gefallenen Kameraden wieder zum Leben zu erwecken.\n\nManche werden sagen, dass unser Handeln falsch ist, aber vieles von dem, was uns widerfahren ist, ist auch falsch. Sollen wir denn solch ein Geschenk wegwerfen?\n\nSie behalten ihre Kritik für sich, wenn unsere Macht die weitere Zerstörung Silbermonds verhindert. Doch sobald sie sich in teuer erkaufter Sicherheit ihren magischen Süchten hingeben können, erheben sie ihre Einsprüche.", sourceObjective = "Füllt das schimmernde Gefäß bei M'uru und kehrt anschließend zu Ritterfürst Heldenblut in Silbermond zurück.", progress = "Habt Ihr schon mit Magister Astalor Blutschwur gesprochen?", completion = "Gut gemacht, {name}. Die vom Licht gewährten Kräfte sind niemals auf 'natürlichem' Wege zu den Blutrittern gekommen, aber wir sind nicht so willensschwach, um unseren Weg von der Natur diktieren zu lassen.\n\nUnsere Beherrschung des Arkanen hat uns einen Pfad durch diese rauen Zeiten eröffnet. Die Kräfte fließen nicht mehr frei in diesen Hallen, doch sie sind da, für die hartnäckigen und willensstarken. Nur wenige sind heutzutage mutig genug, oder verfügen über die Begabung, sie zu meistern, aber ich weiß, dass Ihr den Orden nicht enttäuschen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[64028] = { id = 64028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Sturmwind, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64031] = { id = 64031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64034] = { id = 64034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64035] = { id = 64035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, {name}!" }
quests[64037] = { id = 64037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Östliche Pestländer", description = "Auf Anweisung von Hochlord Bolvar Fordragon ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Lord Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung benötigt Eure Hilfe dabei, die Östlichen Pestländer von der Geißel zu befreien.\n\nUm in die Östlichen Pestländer zu gelangen, sprecht mit dem Greifenmeister Dungar Trinkfest. Seine Greifen können Euch schneller als jedes Pferd dorthin bringen.\n\nFür Ruhm und Ehre der Allianz!", sourceObjective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er wartet in der Kapelle des Hoffnungsvollen Lichts.", completion = "Vielleicht könnt Ihr helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64038] = { id = 64038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dunkle Portal", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAuf Anweisung von Hochlord Bolvar Fordragon ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend in den Verwüsteten Landen zu melden. Sprecht mit Dungar Trinkfest, um einen Flug dorthin zu arrangieren.\n\nSobald Ihr angekommen seid, meldet Euch umgehend bei Wachkommandant Reldorn Netherschwund. Er erwartet Euch vor dem Dunklen Portal...", sourceObjective = "Macht Wachkommandant Reldorn Netherschwund in den Verwüsteten Landen ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", completion = "Willkommen zum Alptraum!", sourceObjectiveStatus = "unverified-source-field" }
quests[64046] = { id = 64046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Orgrimmar, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64047] = { id = 64047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Donnerfels, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung?", sourceObjectiveStatus = "unverified-source-field" }
quests[64048] = { id = 64048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
